(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0015.js"] = [{"id":"poem-64517df4c142a45a8768425b","title":"五祖栽松六祖担柴赞  其三","author":"释了惠","dynasty":"宋","verses":["夯担不担柴，通经不识字。","新州路上人，中书堂里事。","三更月照东禅寺。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-c8ea03fc-2f67-43c2-b6f6-5af7d9656f85","tags":[]},{"id":"poem-6457e32d8136cd94bf7a219d","title":"省题诗二十一首 边城晓角","author":"王棨","dynasty":"唐","verses":["十年抛故国，五夜在边城。","月照沙千里，风吹角一声。","清音飘远戍，残韵落荒营。","背雪征鸿报，眠霜[老鹤惊]。","李陵应下泪，蔡琰岂胜情。","直是吴儿听，[乡关梦不成]。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-75806ff4-71e6-4ebb-bb38-e91d2544a809","tags":[]},{"id":"poem-64581d428b250ed62fe6daf7","title":"梅花一首","author":"华镇","dynasty":"宋","verses":["生来幽意酷怜梅，醉眼愁眉见即开。","案上欲教终日在，林梢令折数枝来。","轻匀素色欺鱼网，潇洒清香压麝煤。","一嗅一观情一倍，熙熙不啻上春台。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-9a9b24c9-76cc-4ef3-b163-f945640c8ecc","tags":[]},{"id":"poem-645e180136967c10923a84d5","title":"行园树","author":"徐铉","dynasty":"宋","verses":["松节凌霜久，蓬根逐吹频。","群生各有性，桃李但争春。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-d7d3fa70-7034-4af3-9ac2-245c6a93d353","tags":[]},{"id":"poem-6467afa007b5442f289c8e6f","title":"萧宅二三子赠答诗二十首 石让竹","author":"卢仝","dynasty":"唐","verses":["自顾拨不转，何敢当主人。","竹弟有清风，可以娱嘉宾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-1d3be722-0840-4501-a2f8-d9c13878355d","tags":[]},{"id":"poem-646a95c287c49e47475bcfb4","title":"素冠","author":"佚名","dynasty":"先秦","verses":["庶见素冠兮，棘人栾栾兮。劳心慱慱兮。","庶见素衣兮，我心伤悲兮。聊与子同归兮。","庶见素𫖒兮，我心蕴结兮。聊与子如一兮。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-146","tags":[]},{"id":"poem-6470b97c0c62e0b9d49f0356","title":"苕之华","author":"佚名","dynasty":"先秦","verses":["苕之华，芸其黄矣。心之忧矣，维其伤矣！","苕之华，其叶青青。知我如此，不如无生！","牂羊坟首，三星在罶。人可以食，鲜可以饱！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-232","tags":[]},{"id":"poem-647448139e57790b3d35891d","title":"鲍老催","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["翠眉谩蹙，赤绳已系夫妇足，芳名已注婚姻牍。","空嗟怨，枉叹息，休推速。","画堂富贵如金谷，休恋故乡生处乐，受恩深处亲骨肉。","(合唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5065","tags":[]},{"id":"poem-6482105d5601bfe9f3670ea1","title":"哭李频员外","author":"曹松","dynasty":"唐","verses":["出麾临建水，下世在公堂。","苦集休开箧，清资罢转郎。","瘴中无子奠，岭外一妻孀。","定是浮香骨，东归就故乡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-d1b2e5e4-d3ba-4f01-a69f-ccda3d6d3b89","tags":[]},{"id":"poem-6484ce65508370c96cd214a9","title":"寄淮海惠泽上人","author":"李洞","dynasty":"唐","verses":["海涛痕满旧征衣，长忆初程宿翠微。","竹里桥鸣知马过，塔中灯露见鸿飞。","眉毫别后应盈尺，嵒木居来定几围。","他日愿师容一榻，煎茶埽地学忘机。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-9b5a02f7-f098-4c6a-bd23-7065bb9b627c","tags":[]},{"id":"poem-6489695f423f31c58369f33a","title":"载驰","author":"佚名","dynasty":"先秦","verses":["载驰载驱，归唁卫侯。驱马悠悠，言至于漕。大夫跋涉，我心则忧。","既不我嘉，不能旋反。视尔不臧，我思不远。","既不我嘉，不能旋济？视尔不臧，我思不閟。","陟彼阿丘，言采其蝱。女子善怀，亦各有行。许人尤之，众稚且狂。","我行其野，芃芃其麦。控于大邦，谁因谁极？大夫君子，无我有尤。百尔所思，不如我所之。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-53","tags":[]},{"id":"poem-648eada864a2bebb65a99bcf","title":"郊庙歌辞 太清宫乐章 真和","author":"不详","dynasty":"唐","verses":["玉磬含香，金炉既馥。","风驭泠泠，云坛肃肃。","杳归大象，霈流嘉福。","俾宁万邦，无思不服。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-69bacbb3-1d7d-4e86-81c5-48f7789a4862","tags":[]},{"id":"poem-648f4c35d98781bafc382e5d","title":"渔歌子·柳如眉","author":"魏承班","dynasty":"五代","verses":["柳如眉，云似发。","姣绡雾縠笼香雪。","梦魂惊，钟漏歇，窗外晓莺残月。","几多情，无处说，落花飞絮清明节。","少年郎，容易别，一去音书断绝。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-12","tags":[]},{"id":"poem-64917cb3b94f6d8130ee8fac","title":"王总卿季和归自关西","author":"释居简","dynasty":"宋","verses":["关西长虑独兢兢，万灶分屯感慨深。","不易制如巫硖水，最难得是蜀人心。","拨灰忍见俱焚玉，铭鼎徐看小篆金。","欲倚筹边开玉帐，共观城外柏森森。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-0d719b71-52d6-47b6-af9f-4f95f557df1f","tags":[]},{"id":"poem-6498872e7f36f385817fd64a","title":"咏史","author":"王丘","dynasty":"唐","verses":["高洁非养正，盛名亦险艰。","伟哉谢安石，携妓入东山。","云岩响金奏，空水滟朱颜。","兰露滋香泽，松风鸣珮环。","歌声入空尽，舞影到池闲。","杳眇同天上，繁华非代间。","卷舒混名迹，纵诞无忧患。","何必苏门子，冥然闭清关。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-a13f9919-7528-4a5d-8347-c7a862412b89","tags":[]},{"id":"poem-64ba2bbcc5461185c2b3d511","title":"采桑子·那能寂寞芳菲节","author":"纳兰性德","dynasty":"清","verses":["那能寂寞芳菲节，欲话生平。","夜已三更。","一阕悲歌泪暗零。","须知秋叶春花促，点鬓星星。","遇酒须倾，莫问千秋万岁名。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-139","tags":[]},{"id":"poem-64ba35878f18c37226990db7","title":"行香子·柳态纤柔","author":"晁补之","dynasty":"宋","verses":["柳态纤柔，雪艳疏明。","问人来、人道轻盈。","张琵莲脸，一寸横波。","比潇洒处，犹难称，此嘉名。","花前烛下，微频浅笑，要题诗、盏畔低声。","司空自惯，狂眼须惊。","也不辞写，双罗带，恐牵情。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-258","tags":[]},{"id":"poem-64c037d8e71c900816a95ab7","title":"奉和圣制送张说巡边","author":"徐知仁","dynasty":"唐","verses":["圣德膺三统，皇恩被八埏。","大明均照物，小丑未宁边。","国相台衡重，元戎庙略宣。","紫泥方受命，黄石乃推贤。","问辠阴山下，安人属国前。","度关行照月，乘障坐消烟。","北阙纡宸藻，南桥列祖筵。","耀威当夏日，杀气指秋天。","鞞鼓鼋鼍振，旌旗鸟兽悬。","由来词翰手，今见勒燕然。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-868fbddc-f0b1-4cd9-b915-017aab829bd6","tags":[]},{"id":"poem-64c3e67a5244adaa0302b8b2","title":"归隐","author":"陈抟","dynasty":"宋","verses":["十年踪迹走红尘，回首青山入梦频。","紫绶纵荣争及睡，朱门虽富不如贫。","愁闻剑戟扶危主，闷听笙歌聒醉人。","携取旧书归旧隐，野花啼鸟一般春。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-歸隱","tags":[]},{"id":"poem-64c5d471f3988bec3a15c075","title":"河满子·无语残妆淡薄","author":"毛熙震","dynasty":"五代","verses":["无语残妆淡薄，含羞亸袂轻盈。","几度香闺眠过晓，绮窗疏日微明。","云母帐中偷惜，水晶枕上初惊。","笑靥嫩疑花坼，愁眉翠敛山横。","相望只教添怅恨，整鬟时见纤琼。","独倚朱扉闲立，谁知别有深情。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-1","tags":[]},{"id":"poem-64c879b7758320134a13a405","title":"偈颂六十七首  其五一","author":"释原妙","dynasty":"宋","verses":["一百禅和三十州，无绳自缚万山头。","谁是护生谁是杀，白云影里铁船浮。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-ff4a9e5d-0f9a-4946-abf4-18de4aa35229","tags":[]},{"id":"poem-64c8da947afa2ad6a452e2d5","title":"念奴娇·当年豪放","author":"蔡伸","dynasty":"宋","verses":["当年豪放，况朋侪俱是，一时英杰。","逸气凌云，佳丽地、独占春花秋月。","冶叶倡条，寻芳选胜，是处曾攀折。","昔游如梦，镜中空叹华发。","邂逅萍梗相逢，十年往事，忍尊前重说。","茂绿成阴春又晚，谁解丁香千结。","宝瑟弹愁，玉壶敲怨，触目堪愁绝。","酒阑人静，为君肠断时节。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-936","tags":[]},{"id":"poem-64c93d8d347ace73ed08a0fe","title":"清平乐·画屏无睡","author":"纳兰性德","dynasty":"清","verses":["画屏无睡，雨点惊风碎。","贪话零星兰焰坠，闲了半床红被。","生来柳絮飘零，便教咒也无灵。","待问归期还未，已看双睫盈盈。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-77","tags":[]},{"id":"poem-64c9f2e946ad8e154e001def","title":"送薛大入洛（伯三七七一下同）","author":"房元阳","dynasty":"唐","verses":["惊年嗟未极，别绪复相依。","雁随春北度，人共水东归。","夜月临轩尽，残灯入晓微。","哀怨一罢曲，幽桂徒芳菲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-245de53e-c50c-45a6-ad1d-9b702eb51178","tags":[]},{"id":"poem-64d673b8c792685e1e7b12d5","title":"荆门行","author":"王建","dynasty":"唐","verses":["江边行人暮悠悠，山头殊未见荆州。","岘亭西南路多曲，栎林深深石镞镞。","看炊红米煮白鱼，夜向鸡鸣店家宿。","南中三月蚊蚋生，黄昏不闻人语声。","生纱帷疎薄如雾，隔衣噆肤耳边鸣。","欲明不待灯火起，唤得官船过蛮水。","女儿停客茆屋新，开门扫地桐花里。","犬声扑扑寒溪烟，人家烧竹种山田。","巴云欲雨薰石热，麋鹿度江虫出穴。","大蛇过处一山腥，野牛惊跳双角折。","斜分汉水横千山，山青水绿荆门关。","向前问个长沙路，旧是屈原沈溺处。","谁家丹旐已南来，逢著流人从此去。","月明山鸟多不栖，下枝飞上高枝啼。","主人念远心不怿，罗衫卧对章台夕。","红烛交横各自归，酒醒还是他乡客。","壮年留滞尚思家，况复白头在天涯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-9bf453d9-38b0-44e5-85b9-f556c7785271","tags":[]},{"id":"poem-64d6e48a7474f51fc83ee075","title":"送僧之宣城","author":"鲍溶","dynasty":"唐","verses":["昔从谢太守，宾客宛陵城。","有日持斋戒，高僧识姓名。","秋风送客去，安得尽忘情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-132b5e93-03cc-44af-a8e9-415f6b37109a","tags":[]},{"id":"poem-64e072f8ea02b2ed956f1f30","title":"韦润州后亭海榴","author":"李嘉祐","dynasty":"唐","verses":["江上年年小雪迟，年光独报海榴知。","寂寂山城风日暖，谢公含笑向南枝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-7f6e313b-5dbb-49b5-b3f9-5df77fff1cbf","tags":[]},{"id":"poem-64e7b1662333c51972c1aa4f","title":"谒金门·留不得","author":"孙光宪","dynasty":"五代","verses":["留不得！留得也应无益。","白纻春衫如雪色，扬州初去日。","轻别离，甘抛掷，江上满帆风疾。","却羡彩鸳三十六，孤鸾还一只。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-38","tags":[]},{"id":"poem-64ea76f1cfa8bd06d399f3a7","title":"阮郎归·湘南楼上好凭栏","author":"向","dynasty":"宋","verses":["湘南楼上好凭栏。","西风吹鼻酸。","宦游何处不惊湍。","白鸥盟已寒。","空饮恨，废追欢。","沈郎衣带宽。","故人休放酒杯干。","而今行路难。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-208","tags":[]},{"id":"poem-64f159d522ed310754e6c550","title":"月夜怀刘秀才","author":"元孚","dynasty":"唐","verses":["独夜相思但自劳，阮生吟罢梦云涛。","此时小定未禅寂，古塔月中松磬高。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-e9c101d4-3425-442b-bce2-dbd80d9f958e","tags":[]},{"id":"poem-650281946ab6f3fb83897109","title":"尾声","author":"施惠《幽闺记》","dynasty":"元","verses":["从今休把光阴负，但畅饮高歌休阻，共醉乐神仙洞府。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3054","tags":[]},{"id":"poem-650f0f93188fbebc120650a4","title":"古兴","author":"聂夷中","dynasty":"唐","verses":["片玉一尘轻，粒粟山丘重。","唐虞贵民食，秪是勤播种。","前圣后圣同，今人古人共。","一岁如苦饥，金玉何所用。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-bc6c2eb5-4930-4b60-a227-7f94fb6a28a8","tags":[]},{"id":"poem-65162e459ecfdea6d035d616","title":"春陪相公看花宴会二首 一","author":"徐凝","dynasty":"唐","verses":["丞相邀欢事事同，玉箫金管咽东风。","百分春酒莫辞醉，明日的无今日红。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-c0d9fb55-eb6b-4c6a-99b9-1a36b1818155","tags":[]},{"id":"poem-6519b38de3f77511c92124c8","title":"龙翔宫","author":"赵崇嶓","dynasty":"宋","verses":["地辟金光界，龙飞析木津。","指麾开辇路，祠祀拜元辰。","天近云光煖，花浓雨脉春。","君王自仁寿，闲杀华封人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-9f2fbb4c-1f5d-47e1-a281-4219dc1a27c8","tags":[]},{"id":"poem-65200fe77d1a3d79d605261d","title":"怀缪竹林","author":"张汝勤","dynasty":"宋","verses":["东风日日恼吟魂，相与论心客在门。","雨洗花光红透骨，风摇野烧翠留痕。","荣枯过眼归春梦，醒醉从人付酒尊。","输与先生专一壑，闲来得看竹生孙。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-a6ccd0ab-4da6-475e-b137-07efa15a95a5","tags":[]},{"id":"poem-652280eaca65c9509167b619","title":"郊庙歌辞 享太庙乐章 景云舞","author":"不详","dynasty":"唐","verses":["惟睿作圣，惟圣登皇。","精感耀魄，时膺会昌。","舜慙大孝，尧推让王。","能事斯极，振古谁方。","文明履运，车书同轨。","巍巍赫赫，尽善尽美。","衢室凝旒，大庭端扆。","释负之寄，事光复子。","脱屣高天，登遐上玄。","龙湖超忽，象野芊绵。","游衣复道，荐果初年。","新庙奕奕，明德配天。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-f53dcca3-2e68-4719-a490-eb845dd6bb79","tags":[]},{"id":"poem-65270230b8ccc61a303e4da7","title":"小游仙诗九十八首 二十三","author":"曹唐","dynasty":"唐","verses":["玉皇赐妾紫衣裳，教向桃源嫁阮郎。","烂煮琼花劝君吃，恐君毛鬓暗成霜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-5682d0fe-9c5e-4f3e-8eab-019e8bc35607","tags":[]},{"id":"poem-65273f46c4dd6c88d4414144","title":"唐明堂乐章 登歌","author":"则天皇后","dynasty":"唐","verses":["礼崇宗祀，志表严禋。","笙镛合奏，文物惟新。","敬遵茂典，敢择良辰。","絜诚斯著，奠谒方申。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-e50e0711-540a-4496-a911-8118d2cb7250","tags":[]},{"id":"poem-65334e26ff80c843c7e4859d","title":"盘隠别驾别造杨龟山祠堂拜奠于三月既望","author":"释居简","dynasty":"宋","verses":["导洛疏伊断在兹，度溪湔祓振荒祠。","人心未泯犹知劝，事力虽殚岂惮为。","清似山阴修禊后，煖于沂上咏归时。","熊罴祥叶期丰报，应有南康别驾儿。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-95ffce06-e05d-426b-876a-5e50c7337285","tags":[]},{"id":"poem-653a14e88675478c2d72064e","title":"减字浣溪沙・浣溪沙·青翰舟中祓禊筵","author":"贺铸","dynasty":"宋","verses":["青翰舟中祓禊筵。","粉娥窥影两神仙。","酒阑飞去作非烟。","重访旧游人不见，雨荷风蓼夕阳天。","折花临水思茫然。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-123","tags":[]},{"id":"poem-6544aa0a3babb648b03533c5","title":"少年行","author":"张籍","dynasty":"唐","verses":["少年从猎出长杨，禁中新拜羽林郎。","独对辇前射双虎，君王手赐黄金珰。","日日鬬鸡都市里，赢得宝刀重刻字。","百里报仇夜出城，平明还在娼楼醉。","遥闻虏到平陵下，不待诏书行上马。","斩得名王献桂宫，封侯起第一日中。","不为六郡良家子，百战始取边城功。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-bc5bbf65-131f-496a-bb4d-656e68f06918","tags":[]},{"id":"poem-654818d3aa7ba1293835bcbc","title":"春秋战国门 苏厉","author":"周昙","dynasty":"唐","verses":["百步穿杨箭不移，养由堪教听弘规。","身隆业著未知退，勿遣功名一旦隳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-a058de3e-23f0-485e-949c-1b0e3af892aa","tags":[]},{"id":"poem-654dc7b647e2048d7fc8a17e","title":"和主司王起","author":"石贯","dynasty":"唐","verses":["重德由来为国生，五朝清显冠公卿。","风波久伫济川檝，羽翼三迁出谷莺。","绛帐青衿同日贵，春兰秋菊异时荣。","孔门弟子皆贤哲，谁料穷儒忝一名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-0df9c129-217f-4c79-9bf7-536b449c9e04","tags":[]},{"id":"poem-65539efdd1f36d3c20461f08","title":"柳枝·解冻风来末上青","author":"牛峤","dynasty":"五代","verses":["解冻风来末上青，解垂罗袖拜卿。","无端袅娜临官路，舞送行人过一生。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-45","tags":[]},{"id":"poem-655707c48069e29a0b776243","title":"千秋岁引·别馆寒砧","author":"王安石","dynasty":"宋","verses":["别馆寒砧，孤城画角。","一派秋声入寥廓。","东归燕从海上去，南来雁向沙头落。","楚台风，庾楼月，宛如昨。","无奈被些名利缚。","无奈被他情担阁。","可惜风流总闲却。","当初漫留华表语，而今误我秦楼约。","梦阑时，酒醒后，思量著。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-17","tags":["宋词三百首"]},{"id":"poem-655dd331c24e59b75ac7fb16","title":"咏史诗 葛陂","author":"胡曾","dynasty":"唐","verses":["长房回到葛陂中，人已登真竹化龙。","莫道神仙难顿学，嵇生自是不遭逢。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-797d83fd-d95f-418b-b47b-ccdbc911200e","tags":[]},{"id":"poem-655ed837a42de5ce04c1707a","title":"九叹·愍命","author":"刘向","dynasty":"汉","verses":["昔皇考之嘉志兮，喜登能而亮贤。","情纯洁而罔薉兮，姿盛质而无愆。","放佞人与谄谀兮，斥谗夫与便嬖。","亲忠正之悃诚兮，招贞良与明智。","心溶溶其不可量兮，情澹澹其若渊。","回邪辟而不能入兮，诚原藏而不可迁。","逐下袟于后堂兮，迎虙妃于伊雒。","刜谗贼于中廇兮，选吕管于榛薄。","丛林之下无怨士兮，江河之畔无隐夫。","三苗之徒以放逐兮，伊皋之伦以充庐。","今反表以为里兮，颠裳以为衣。","戚宋万于两楹兮，废周邵于遐夷。","却骐骥以转运兮，腾驴骡以驰逐。","蔡女黜而出帷兮，戎妇入而彩绣服。","庆忌囚于阱室兮，陈不占战而赴围。","破伯牙之号钟兮，挟人筝而弹纬。","藏瑉石于金匮兮，捐赤瑾于中庭。","韩信蒙于介胄兮，行夫将而攻城。","莞芎弃于泽洲兮，瓟瓥蠹于筐簏。","麒麟奔于九皋兮，熊罴群而逸囿。","折芳枝与琼华兮，树枳棘与薪柴。","掘荃蕙与射干兮，耘藜藿与蘘荷。","惜今世其何殊兮，远近思而不同。","或沉沦其无所达兮，或清激其无所通。","哀余生之不当兮，独蒙毒而逢尤。","虽謇謇以申志兮，君乖差而屏之。","诚惜芳之菲菲兮，反以兹为腐也。","怀椒聊之蔎蔎兮，乃逢纷以罹诟也。","叹曰：嘉皇既殁终不返兮，山中幽险郢路远兮。","谗人𬣡𬣡孰可愬兮，征夫罔极谁可语兮。","行吟累欷声喟喟兮，怀忧含戚何侘傺兮。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-53","tags":[]},{"id":"poem-656c1add684f795250a376f9","title":"春秋战国门 再吟","author":"周昙","dynasty":"唐","verses":["戏问将何对所耽，滑稽无骨是常谭。","昔时王者皆通四，近见君王祗好三。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-74b0fec8-ca73-46d9-92dd-9c91fef9cf5e","tags":[]},{"id":"poem-657035d8853dc8d848e8eb72","title":"沧浪峡","author":"李山甫","dynasty":"唐","verses":["走毂飞蹄过此傍，几人留意问沧浪。","烟波莫笑趋名客，为爱朝宗日夜忙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-b6967cf9-7689-4b9a-b18d-81a39068b6ef","tags":[]},{"id":"poem-65789af51be946ce9c210445","title":"洞仙歌·当时我醉","author":"晁补之","dynasty":"宋","verses":["当时我醉，美人颜色，如花堪悦。","今日美人去，恨天涯离别。","青楼朱箔，婵娟蟾桂，三五初圆，伤二八、还又缺。","空伫立，一望一见心绝。","心绝。","顿成凄凉，千里音尘，一梦欢娱，推枕惊巫山远，洒泪对湘江阔。","美人不见，愁人看花，心乱含愁，奏绿绮、弦清切。","何处有知音，此恨难说。","怨歌未阕。","恐暮雨收、行云歇。","窗梅发。","乍似睹、芳容冰洁。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-152","tags":[]},{"id":"poem-657e519041971b63ce49a7bd","title":"示淳谦首座持钵","author":"释原妙","dynasty":"宋","verses":["千家万家，总是维摩丈室。","十斛百斛，无非达磨眼睛。","若向遮里会得，何劳向外经营。","其或未然，咄，酒肆淫坊休放过，龙宫虎穴要亲临。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-a75fb2b1-bc63-4611-af3d-e328c1d642e2","tags":[]},{"id":"poem-659441bb9e66a6fd1ddb8552","title":"丘中有麻","author":"佚名","dynasty":"先秦","verses":["丘中有麻，彼留子嗟。彼留子嗟，将其来施施。","丘中有麦，彼留子国。彼留子国，将其来食。","丘中有李，彼留之子。彼留之子，贻我佩九。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-73","tags":[]},{"id":"poem-659684d8bf75633c46fbd53a","title":"南乡子·岸远沙平","author":"欧阳炯","dynasty":"五代","verses":["岸远沙平，日斜归路晚霞明。","孔雀自怜金翠尾，临水，认得行人惊不起。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-2","tags":[]},{"id":"poem-65985c4c84eda67a446d86ce","title":"生查子·寂寞画堂空","author":"魏承班","dynasty":"五代","verses":["寂寞画堂空，深夜垂罗幕。","灯暗锦屏欹，月冷珠帘薄。","愁恨梦难成，何处贪欢乐。","看看又春来，还是长萧索。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-10","tags":[]},{"id":"poem-6599aa3e9524ec8e5fc50aeb","title":"夏夜叹","author":"杜甫","dynasty":"唐","verses":["永日不可暮，炎蒸毒我肠。","安得万里风，飘飖吹我裳。","昊天出华月，茂林延疎光。","仲夏苦夜短，开轩纳微凉。","虚明见纤毫，羽虫亦飞扬。","物情无巨细，自适固其常。","念彼荷戈士，穷年守边疆。","何由一洗濯，执热互相望。","竟夕击刁斗，喧声连万方。","青紫虽被体，不如早还乡。","北城悲笳发，鹳鹤号且翔。","况复烦促倦，激烈思时康。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-c63d308b-f3a7-4520-b041-f7f4e27a5c9d","tags":["忧国忧民","夏天"]},{"id":"poem-659a91da687f20783169cd92","title":"游长宁公主流杯池二十五首 十一","author":"上官昭容","dynasty":"唐","verses":["暂尔游山第，淹留惜未归。","霞窗明月满，涧户白云飞。","书引藤为架，人将薜作衣。","此真攀玩所，临睨赏光辉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-cec1b138-6e5a-4e43-963b-7dae24a295fc","tags":[]},{"id":"poem-659b399fcc89bfc3cb204760","title":"次韵湖南张运判会春园新亭之什","author":"华镇","dynasty":"宋","verses":["落落长松满古园，沈沈碧水侵新轩。","于今人物情虽别，平昔池台迹未昏。","身外无尘红入座，眼前有酒绿盈樽。","更将好乐无荒意，深入无生不二门。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-e82400b8-1322-4589-95d8-bc0fccff0a76","tags":[]},{"id":"poem-65b7f3fbd694009c287ddb2f","title":"打球图","author":"晁无咎","dynasty":"宋","verses":["阊阖千门万户开，三郎沈醉打球回。","九龄已老韩休死，无复明朝谏疏来。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-打球圖","tags":[]},{"id":"poem-65bbe65987aea4fcaf9fa8ef","title":"环翠亭","author":"陈知柔","dynasty":"宋","verses":["当年把臂入龙山，犹记相逢醉梦间。","君似孤云了无碍，我如倦翼早知还。","茅簷负日真成算，竹榻论诗整破颜。","欲问太平真气象，夜来风月到松关。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-acc35d21-3349-4e88-bf4a-fa4d0252ba3f","tags":[]},{"id":"poem-65c2fc4ef17c98387abdfa7b","title":"霓裳中序第一·亭皋正望极","author":"姜夔","dynasty":"宋","verses":["亭皋正望极。","乱落江莲归未得。","多病却无气力。","况纨扇渐疏，罗衣初萦。","流光过隙。","叹杏梁、双燕如客。","人何在，一帘淡月，仿佛照颜色。","幽寂。","乱蛩吟壁。","动庾信、清愁似织。","沈思年少浪迹。","笛里关山，柳下坊陌。","坠红无信息。","漫暗水，涓涓溜碧。","漂零久，而今何意，醉卧酒垆侧。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-125","tags":["宋词三百首"]},{"id":"poem-65c5e133f7ba00af9dca2283","title":"效古促促曲为河上思妇作","author":"李益","dynasty":"唐","verses":["促促何促促，黄河九回曲。","嫁与棹船郎，空床将影宿。","不道君心不如石，那教妾貌长如玉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-6ce804ea-013c-4af4-a4c3-4e1e4fb89500","tags":["黄河"]},{"id":"poem-65c903630bc8ae5d66d5ebf0","title":"王昭君","author":"胡令能","dynasty":"唐","verses":["胡风似劒锼人骨，汉月如钩钓胃肠。","魂梦不知身在路，夜来犹自到昭阳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-cea26d6c-4b88-4982-a31b-f01aead537e6","tags":[]},{"id":"poem-65d2e821277071e4c08f0bdc","title":"阮郎归·旧香残粉似当初","author":"晏几道","dynasty":"宋","verses":["旧香残粉似当初。","人情恨不如。","一春犹有数行书。","秋来书更疏。","衾凤冷，枕鸳孤。","愁肠待酒舒。","梦魂纵有也成虚。","那堪和梦无。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-29","tags":["宋词三百首"]},{"id":"poem-65d692fdc5ed4a963c24ade8","title":"五六","author":"王梵志","dynasty":"唐","verses":["有钱莫掣⿰忄霍，（「⿰忄霍」，伯三七一六、伯三六五六卷作「攉」。","）不得是（一本作「事」。","）奢华。","乡里人儜恶，差科必破家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-7b579402-909a-4aa6-bec6-fac43e2e9143","tags":[]},{"id":"poem-65d791b39543c59485d800f5","title":"风不鸣条","author":"卢肇","dynasty":"唐","verses":["习习和风至，过条不自鸣。","暗通青律起，远傍白苹生。","拂树花仍落，经林鸟自惊。","几牵萝蔓动，潜惹柳丝轻。","入谷迷松响，开窗失竹声。","薰弦方在御，万国仰皇情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-b95fdfcb-149d-46e7-a72c-5279ad03975b","tags":[]},{"id":"poem-65d8054b9f7c8b9cb784b917","title":"狂题十八首 七","author":"司空图","dynasty":"唐","verses":["老禅乘仗莫过身，远岫孤云见亦频。","应是佛边犹怕闹，信缘须作且闲人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-b794d29b-4f8e-4a4b-847c-4371fdf15c04","tags":[]},{"id":"poem-65dae24a6028cbf21bb37ed1","title":"登临川仙台观南亭","author":"李翔","dynasty":"唐","verses":["独倚危栏爱景晴，古松坛殿半阴横。","东山有路干云险，汝水无波到底清。","归洞鬬龙收雨脚，拂簷行雁起秋声。","开襟正是忘机处，不觉疏钟遍郡城。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-d98076a5-e805-4f4e-b53c-ab15f7eb432d","tags":[]},{"id":"poem-65dc4fb1ecc716ad6c405a82","title":"思平泉树石杂咏一十首 似鹿石","author":"李德裕","dynasty":"唐","verses":["林中有奇石，髣髴兽潜行。","乍似依岩桂，还疑食野苹。","茸长绿藓映，斑细紫苔生。","不是见羇者，何劳如顿缨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-13dc5e49-a70c-4cc0-bb86-c8b70f62f22b","tags":[]},{"id":"poem-65f618e140b888503614f871","title":"小重山·门外东风糁玉尘","author":"毛滂","dynasty":"宋","verses":["门外东风糁玉尘。","曲房花气蔼，博山春。","小槽珠滴桂椒芬。","梅蕊绽，谁共醉中闻。","睡起静无人。","曲屏横远翠，锦为邻。","十年旧事梦如新。","红蕤枕，犹暖楚峰云。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-750","tags":[]},{"id":"poem-65fc30420ed78bd7ed692372","title":"生查子·正月到盘洲","author":"洪适","dynasty":"宋","verses":["正月到盘洲，解冻东风至。","便有浴鸥飞，时见潜鳞起。","高柳送青来，春在长林里。","绿萼一枝梅，端是花中瑞。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-719","tags":[]},{"id":"poem-66019de46accd252d8def43a","title":"戏呈吴冯","author":"皎然","dynasty":"唐","verses":["世人不知心是道，只言道在他方妙。","还如瞽者望长安，长安在西向东笑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-55593b78-8ce4-413b-ab56-cd3d3416e319","tags":[]},{"id":"poem-66063e2c64d3c6ccd579eb8e","title":"醉蓬莱·见处即已","author":"吴穆仲","dynasty":"宋","verses":["见处即已，无心即了。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-808","tags":[]},{"id":"poem-6616bdec85522bbd2d24ad85","title":"宿扬州水馆","author":"李绅","dynasty":"唐","verses":["舟依浅岸参差合，桥映晴虹上下连。","轻檝过时摇水月，远灯繁处隔秋烟。","却思海峤还凄叹，近涉江涛更凛然。","闲凭栏干指星汉，尚疑轩盖在楼船。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-e23faa15-b7c4-4801-9010-de99c8fe405e","tags":[]},{"id":"poem-661dedf8fb021acfea4c8dcc","title":"开圣寺","author":"张祜","dynasty":"唐","verses":["西去山门五里程，粉牌书字甚分明。","萧帝坏陵深虎迹，广师遗院闭松声。","长廊画剥僧形影，古壁尘昏客姓名。","何必更将空理遣，眼前人事已浮生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-0d3d1cb6-94b8-401c-b450-182b2b5991b3","tags":[]},{"id":"poem-661ea42713d1c20b691289e9","title":"送郑侍御谪闽中","author":"高适","dynasty":"唐","verses":["谪去君无恨，闽中我旧过。","大都秋雁少，只是夜猿多。","东路云山合，南天瘴疠和。","自当逢雨露，行矣慎风波。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-3898eb6d-95df-4b2e-b6d2-348e3f013d5a","tags":["送别","劝勉","友情"]},{"id":"poem-6623261e7bd636b7a1c6fed8","title":"思帝乡·春日游","author":"韦庄","dynasty":"五代","verses":["春日游，杏花吹满头。","陌上谁家年少，足风流。","妾拟将身嫁与，一生休。","纵被无情弃，不能羞！"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-15","tags":[]},{"id":"poem-6625bd15e7a346a7eb42b20d","title":"庚戌正月一日游都峤山留五绝句栖真观中  其二","author":"李纲","dynasty":"宋","verses":["松岭云峰步步佳，芒鞋竹杖极幽遐。","使君不得同清赏，正恐山将翠幕遮。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-5f892e51-ef5a-4941-8e51-ef9cded1c311","tags":[]},{"id":"poem-66271a48108ba4617c91b6f3","title":"观永乐公主入番","author":"孙逖","dynasty":"唐","verses":["边地莺花少，年来未觉新。","美人天上落，龙塞始应春。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-觀永樂公主入番","tags":[]},{"id":"poem-6627f082080d3251a07c5b41","title":"书琵琶背","author":"后主煜","dynasty":"唐","verses":["侁自肩如削，难胜数缕绦。","天香留凤尾，余煖在檀槽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-bbf02817-86a8-42de-b8bf-9d13c764fdb3","tags":["怀人","悼亡"]},{"id":"poem-6629a5dbcdd6f27a766f59fb","title":"罢相作","author":"李适之","dynasty":"唐","verses":["避贤初罢相，乐圣且衔杯。","为问门前客，今朝几个来。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-罷相作","tags":[]},{"id":"poem-662edf019b1c525d5db37f55","title":"赠贾岛","author":"张籍","dynasty":"唐","verses":["篱落荒凉僮仆饥，乐游原上住多时。","蹇驴放饱骑将出，秋卷装成寄与谁。","拄杖傍田寻野菜，封书乞米趂时炊。","姓名未上登科记，身屈惟应内史知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-33be17f8-f0b2-4c54-9d97-d4900b2c1f31","tags":[]},{"id":"poem-6638cd0fe2fac760ee0a38a9","title":"步步娇","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(小生上)哥哥嫂嫂回家去，心下休疑虑，多应中计矣！喜得门头，巡军皆睡，将尸埋在土沙中，回去说详细。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1927","tags":[]},{"id":"poem-663cd76a9d2a11a16f43e012","title":"赠维扬故人","author":"徐铉","dynasty":"宋","verses":["东京少长认维桑，书剑谁教入帝乡。","一事无成空放逐，故人相见重凄凉。","楼台寂寞官河晚，人物稀疏驿路长。","莫怪临风惆怅久，十年春色忆维扬。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-a42af670-1dc2-4202-8edc-b61424a62c5e","tags":[]},{"id":"poem-6643eedf1c16a1bb057270ca","title":"句","author":"元晦","dynasty":"唐","verses":["石静如开镜，山高若耸莲。","笋竿抽玉管，花蔓缀金钿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-7645f905-1a7f-4770-90cc-b8e49bf15d60","tags":[]},{"id":"poem-6647ff673aa7e8a26ed4e962","title":"春宵（原作「霄」）有怀","author":"佚名","dynasty":"唐","verses":["独坐春宵（原作「霄」）月见高，月下思君心郁陶。","踌躇不觉三更尽，空见豺狼数遍号。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-355b0eeb-afcd-4677-a198-9ab96bdfd70e","tags":[]},{"id":"poem-664a5031ce1b36cedd7d8e4a","title":"忆王孙·西风一夜剪芭蕉","author":"纳兰性德","dynasty":"清","verses":["西风一夜剪芭蕉，倦眼经秋耐寂寥。","强把心情付浊醪。","读《离骚》。","愁似湘江日夜潮。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-24","tags":[]},{"id":"poem-664a63e70586fa897fe5dc42","title":"对月寄雍陶","author":"刘得仁","dynasty":"唐","verses":["圆明寒魄上，天地一光中。","临水通宵坐，知君此兴同。","华凝衣有露，静极树无风。","若向湘江见，湘江彻底空。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-ecebd171-37e0-4cc4-af91-4fdb3cc8b99d","tags":[]},{"id":"poem-664cc856946b26dfb015a97f","title":"汶归舟中","author":"赵文","dynasty":"宋","verses":["咿咿轧轧橹声歇，凄凄切切寒蛩鸣。","满空星斗不解语，时与渔火争晶荧。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-df35991a-744c-4234-a2da-411bb53ef906","tags":[]},{"id":"poem-664d78c5560e93d67541d7ea","title":"桃源行","author":"释居简","dynasty":"宋","verses":["种桃种得春一原，逃死逃得秦外天。","杀鸡为黍替草具，不识晋语犹秦言。","昨日相逢今日别，流水落花行路绝。","鸡黍更从仙隠设，疑是齐东野人说。","典午乱多仍治少，此事明明不分晓。","一秦才灭一秦生，避世避人还避秦。","忆昔怒驱丞相去，犹思上蔡东门兔。","纵有封君禄万锺，争如食邑桃千树。","空山惜日见日长，秦民怨日偕日亡。","恨身不为治时草，不恨祖龙长不老。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-0525a984-bf30-44ce-8581-ad8261059d91","tags":[]},{"id":"poem-6654712f64ede949403e3aac","title":"贾生","author":"李商隐","dynasty":"唐","verses":["宣室求贤访逐臣，贾生才调更无伦。","可怜夜半虚前席，不问苍生问鬼神。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-02456f60-6ab5-4de8-b9ed-f7519818f0ca","tags":["唐诗三百首","隋・唐・五代","托古讽今","七言绝句","怀才不遇"]},{"id":"poem-665ca801afd296b4a256a838","title":"永明山居诗（六十九首） 六十二","author":"延寿","dynasty":"唐","verses":["绿柳堤边春色多，数树重重袅翠萝。","红白花枝争鬬发，晴阴天气半相和。","中山谩醉千壶酒，易水徒悲一曲歌。","尘世无凭唯道外，荣枯瞬息尽消磨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-2abf200e-aa98-420a-b5d8-ee6b5a31ae87","tags":[]},{"id":"poem-666e426d366a997a45cb499b","title":"有赠","author":"赵崇鉘","dynasty":"宋","verses":["别意参差绕碧栏，外头斜月逼人寒。","钩帘恐碍双栖鹊，乍可桃花隔雾看。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-08aaa023-cb75-4f3a-ad48-ee3bdcfc41d5","tags":[]},{"id":"poem-6670111cdfe56d33f5d0fb0d","title":"玉楼春·春入横塘摇浅浪","author":"牛峤","dynasty":"五代","verses":["春入横塘摇浅浪，花落小园空惆怅。","此情谁信为狂夫，恨翠愁红流枕上。","小玉窗前嗔燕语，红泪滴窗金线缕。","雁归不见报郎归，织成锦字封过与。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-23","tags":[]},{"id":"poem-6670278589d26a22dd101891","title":"送咸安公主","author":"孙叔向","dynasty":"唐","verses":["卤簿迟迟出国门，汉家公主嫁乌孙。","玉颜便向穹庐去，卫霍空承明主恩。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-4f3fd12d-8dd2-41b7-a5ef-62aa300a3bbe","tags":[]},{"id":"poem-667911d5459ef2513953aa1d","title":"小游仙诗九十八首 四十五","author":"曹唐","dynasty":"唐","verses":["欲饮尊中云母浆，月明花里合笙簧。","更教小奈将龙去，便向金坛取阮郎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-c93c7466-1efd-4d93-968b-611e5e834804","tags":[]},{"id":"poem-6684244fd54ba71c9fce6d02","title":"洋州三十景 横湖","author":"鲜于侁","dynasty":"宋","verses":["三冬修竹色，六月芙蕖风。","轩窗复起处，尽入菱花中。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-f3ca00c9-f54a-4971-adf5-eed79d75c3b3","tags":[]},{"id":"poem-668821874c53cd65a994b219","title":"赠永崇李将军充襄阳制置使","author":"李洞","dynasty":"唐","verses":["拜官门外发辉光，宿卫阴符注几行。","行处近天龙尾滑，猎时陪帝马鬃香。","九城王气生旗队，万里寒风入箭疮。","从此浩然声价歇，武中还有李襄阳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-4bdfd85c-9868-42a1-9e01-301eb9283f63","tags":[]},{"id":"poem-668a410e23ee14e8b90ebba9","title":"奉和圣制送张说上集贤学士赐宴","author":"韦述","dynasty":"唐","verses":["修文中禁启，改字令名加。","台座征人杰，书坊应国华。","赋诗开广宴，赐酒酌流霞。","云散明金阙，池开照玉沙。","掖垣留宿鸟，温树落余花。","谬此天光及，衔恩醉日斜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-3b115a49-2dcc-445a-96c2-4e9129d8a72f","tags":[]},{"id":"poem-668b50c31f2e1a5180e639e3","title":"夜坐","author":"宋伯仁","dynasty":"宋","verses":["柏香烟里瀹山茶，穷似烧丹道士家。","窗纸渐明寒月上，一肱清梦入梅花。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-13ab296a-d6b5-4d9a-81a7-1e03cd39ad96","tags":[]},{"id":"poem-668dd762dffb2139188e06ce","title":"颂古三十一首  其一七","author":"释原妙","dynasty":"宋","verses":["吞而复吐冷烟浮，月落寒山犹未休。","重把丝纶轻一掣，岂知元只在钩头。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-ff9a08d7-6254-4b42-b9c8-34b34e8c906e","tags":[]},{"id":"poem-668e884ab8faba549cf4741b","title":"柰子花","author":"萧德祥《小孙屠》","dynasty":"元","verses":["相将岳帝生干日，欲同去烧香献纸。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8630","tags":[]},{"id":"poem-6694728a8f3a94b02769ab03","title":"亭前柳","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(净)老儿垂鬓已星星，弱体战兢兢。","况兼寒凛凛。","那更冷清清。","此行怎去登山岭？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8297","tags":[]},{"id":"poem-6697f3d15496d385503605b9","title":"采莲子·菡萏香莲十顷陂","author":"皇甫松","dynasty":"唐","verses":["菡萏香莲十顷陂（举棹），小姑贪戏采莲迟（年少）。","晚来弄水船头湿（举棹），更脱红裙裹鸭儿（年少）。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-26","tags":[]},{"id":"poem-669af862c388ca203cf63c63","title":"咏史","author":"刘知几","dynasty":"唐","verses":["泛泛水中蓱，离离岸傍草，逐浪高复下，从风起还倒。","人生不若兹，处世安可保？","遽瑗仕卫国，屈伸随世道；方朔隐汉朝，易农以为宝。","饮啄得其性，从容成寿考。","南国有狂生，形容独枯槁，作赋刺椒兰，投江溺流潦。","达人无不可，委军（运）推苍昊；何为明白（自）销[一]，取讥于楚老？","（[一]、王云：「『军』疑应作『运』『白』疑应作『自』，用《汉书·龚胜传》语。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-aab41025-4350-4ee5-ae77-71dd10dd3913","tags":[]},{"id":"poem-66a8b98f057aa26b29c5d101","title":"鹧鸪天·王母瑶池景物鲜","author":"崔敦礼","dynasty":"宋","verses":["王母瑶池景物鲜。","蟠桃华宝不知年。","天教把定春风笑，来作人间长寿仙。","披蕊芨，诵云篇。","朝朝香火篆炉烟。","只将清静为真乐，合住春秋岁八千。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-406","tags":[]},{"id":"poem-66a8d9b9a89dd4d481606afe","title":"润州送师弟自江夏往台州","author":"崔峒","dynasty":"唐","verses":["远客乘流去，孤帆向夜开。","春风江上使，前日汉阳来。","别路犹千里，离心重一杯。","剡溪木未落，羡尔过天台。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-4f0f738a-0f5a-4646-8f7e-21f4a86c763d","tags":[]},{"id":"poem-66af4064e1d1dafe68180825","title":"钱百六录参入新宅得子","author":"释居简","dynasty":"宋","verses":["千忆子孙昌，衣传衮绣光。","厦成观贺燕，笔喜误书麞。","桂熟霜前子，梅腾雪后芳。","不须瞻岐嶷，定肖白眉良。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-090ffbbe-f89f-47d8-a68c-4920a0e508ac","tags":[]},{"id":"poem-66af703fa7a6f9d7a6ead515","title":"御街行·画船横倚烟溪半","author":"张先","dynasty":"宋","verses":["画船横倚烟溪半。","春入吴山遍。","主人凭客且迟留，程入花溪远远。","数声芦叶，两行霓袖，几处成离宴。","纷纷归骑亭皋晚。","风顺樯乌转。","古今为别最消魂，因别有情须怨。","更独自、尽上高台望，望尽飞云断。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-297","tags":[]},{"id":"poem-66b1b939e47dd7f5a1e868ad","title":"伤春","author":"杨万里","dynasty":"宋","verses":["准拟今春乐事浓，依然枉却一东风。","年年不带看花眼，不是愁中即病中。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-傷春","tags":[]},{"id":"poem-66b959ab52d16e4d105c82b1","title":"暮秋迁客增思寄京华","author":"李嘉祐","dynasty":"唐","verses":["宋玉怨三秋，张衡复四愁。","思乡雁北至，欲别水东流。","倚树看黄叶，逢人诉白头。","佳期不可失，落日自登楼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-0167aaca-d4f5-4e4b-9fb8-bd29260f31b7","tags":[]},{"id":"poem-66bb49215bfef7436e64b720","title":"瓶梅","author":"宋伯仁","dynasty":"宋","verses":["南枝斜插古军持，瘦影参差落砚池。","莫道人家窗户暖，等闲忘却陇头时。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-820c167d-3627-4281-b424-6a9732bced39","tags":[]},{"id":"poem-66be53309059f8902a1b46f3","title":"郊庙歌辞 梁郊祀乐章 庆熙","author":"赵光逢、张衮","dynasty":"唐","verses":["哲后躬享，旨酒斯陈。","王恭无斁，严祀维夤。","皇祖以配，大孝以振。","宜锡景福，永休下民。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-323842d9-5424-473b-b736-17a756fa6bb8","tags":[]},{"id":"poem-66ca3c90ea5a1b789af2f40d","title":"拟古·高云媚春日","author":"纳兰性德","dynasty":"清","verses":["高云媚春日，坐觉鱼鸟亲。","可怜暮春候，病中别故人。","莺啼花乱落，风吹成锦茵。","君去一何速，到家垂柳新。","芙蓉湖上月，照君垂长纶。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-222","tags":[]},{"id":"poem-66ce04011ddeee8d88d1ae47","title":"蠡泽旅怀","author":"林滋","dynasty":"唐","verses":["谁言行旅日，况复桃花时。","水即沧溟远，星从天汉垂。","川光独鸟暮，林色落英迟。","岂是王程急，偏多游子悲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-37033da7-e91a-442b-99d0-08013f7f359f","tags":[]},{"id":"poem-66d4d597559c3cef4d6434e3","title":"碧牡丹·步帐摇红绮","author":"张先","dynasty":"宋","verses":["步帐摇红绮。","晓月堕，沈烟砌。","缓板香檀，唱彻伊家新制。","怨入眉头，敛黛峰横翠。","芭蕉寒，雨声碎。","镜华翳。","闲照孤鸾戏。","思量去时容易。","钿盒瑶钗，至今冷落轻弃。","望极蓝桥，但暮云千里。","几重山，几重水。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-425","tags":[]},{"id":"poem-66e1294c1a4e44d41245bc75","title":"天官崔侍郎夫人卢氏挽歌","author":"沈佺期","dynasty":"唐","verses":["偕老言何谬，香魂事永违。","潘鱼从此隔，陈凤宛然飞。","埋镜泉中暗，藏镫地下微。","犹凭少君术，仿佛覩容辉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-72b48e21-072a-464e-afc5-1576f7357086","tags":[]},{"id":"poem-66e1f452219c43c103a4ce21","title":"姑苏行","author":"皎然","dynasty":"唐","verses":["古台不见秋草衰，却忆吴王全盛时。","千年月照秋草上，吴王在时几回望。","至今月出君不还，世人空对姑苏山。","山中精灵安可覩，辙迹人踪麋鹿聚。","婵娟西子倾国容，化作寒陵一堆土。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-db95391f-b0af-4027-addd-6e970841188e","tags":[]},{"id":"poem-66e5bf1d3eb9694065c09788","title":"偈颂（幷序○序为南岳齐己撰） 十四","author":"居遁","dynasty":"唐","verses":["此生不息息何时，息在今生共要知。","心息仙因（《景德传灯录》卷二九作「只缘」）无妄想，妄空（《景德传灯录》作「除」）心息是休时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-bf200ae5-48f8-4041-bceb-598b808a68ab","tags":["衡山"]},{"id":"poem-66e7d1c8a8e3078869757beb","title":"渔歌子·楚山青","author":"李珣","dynasty":"五代","verses":["楚山青，湘水绿，春风淡荡看不足。","草芊芊，花簇簇，渔艇棹歌相续。","信浮沉，无管束，钓回乘月归湾曲。","酒盈樽，云满屋，不见人间荣辱。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-17","tags":[]},{"id":"poem-66e86a7d8327b35b7c2fa07e","title":"宿天竺寺寄灵隐寺僧","author":"张籍","dynasty":"唐","verses":["夜向灵溪息此身，风泉竹露净衣尘。","月明石上堪同宿，那作山南山北人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-89d241bf-37ef-4ce6-9230-1354cb508faa","tags":[]},{"id":"poem-66ec60ca219e0c68d7b2a357","title":"谒金门·香乍起","author":"曹勋","dynasty":"宋","verses":["香乍起。","满院垂垂岩桂。","未卷珠帘香已至。","酒杯言笑里。","叶下茸金繁蕊。","别是清妍风致。","更远随人闻细细。","月华天似水。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-159","tags":[]},{"id":"poem-66fda7bc4df32cbeb27440b6","title":"浣溪沙·无恙年年汴水流","author":"纳兰性德","dynasty":"清","verses":["无恙年年汴水流。","一声水调短亭秋。","旧时明月照扬州。","曾是长堤牵锦缆，绿杨清瘦至今愁。","玉钩斜路近迷楼。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-51","tags":[]},{"id":"poem-66fe835983e6cfd6951e55e0","title":"林主簿明仲挽词  其二","author":"王十朋","dynasty":"宋","verses":["一箭双雕手，青衫已白头。","砚几磨铁尽，官止及瓜休。","漏断鄞江梦，风含曲水愁。","钧天记白玉，麈世冷西楼。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-237c187d-b53a-4e26-b60e-6c552626a549","tags":[]},{"id":"poem-6700676b6db41a7755f02c78","title":"晏坐岩","author":"陈岩","dynasty":"宋","verses":["掠地霜风黄叶飞，山人晏坐已多时。","但知六凿俱通透，不省支床旧有龟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-a0a22846-dcae-425e-adbd-318ada39e4c3","tags":[]},{"id":"poem-6703e870afe46531ba889892","title":"清平乐·洛阳愁绝","author":"温庭筠","dynasty":"唐","verses":["洛阳愁绝，杨柳花飘雪。","终日行人恣攀折，桥下流水呜咽。","上马争劝离觞，南浦莺声断肠。","愁杀平原年少，回首挥泪千行。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-1","tags":[]},{"id":"poem-670dbfde95339f1f401b64c6","title":"梅花落","author":"沈佺期","dynasty":"唐","verses":["铁骑几时回，金闺怨早梅。","雪寒花已落，风暖叶应开。","夕逐新春管，香迎小岁杯。","盛时何足贵，书里报轮台。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-7fee8bf1-2306-4b76-96a2-6d014212f320","tags":[]},{"id":"poem-67104ad1fe652b9148f6e3e3","title":"有客","author":"释居简","dynasty":"宋","verses":["雨止云犹黑，春寒草未青。","打门无俗客，勒驾有山灵。","仿佛斜川路，裴回曲水亭。","落梅都著子，点点六花零。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-d43ed53c-5a35-4186-9201-2f204b27bdde","tags":[]},{"id":"poem-671bbea021ca853f488d9566","title":"江行无题一百首 四十七","author":"钱珝","dynasty":"唐","verses":["海月非常物，等闲不可寻。","披沙应有地，浅处定无金。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-e6cf5454-bd77-436b-b372-8ff55066fd69","tags":[]},{"id":"poem-6728d80d711d89004d8f352c","title":"诗三首  其三","author":"米芾","dynasty":"宋","verses":["闲中无所事，得意思同论。","约月升崇观，校射出平原。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-d616777e-4178-43a3-93e3-744a98c5f371","tags":[]},{"id":"poem-6729d072a6a1263ce51693fa","title":"咏史诗 鲁城","author":"胡曾","dynasty":"唐","verses":["鲁公城阙已丘墟，荒草无由认玉除。","因笑臧孙才智少，东门钟鼓祀鶢鶋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-b353d75d-8f32-4b2b-836b-643f2f5a4887","tags":[]},{"id":"poem-6729fb9999b648492e0cb0b2","title":"示二子","author":"陈俊卿","dynasty":"宋","verses":["兴来文字三杯酒，老去生涯万卷书。","遗汝子孙清白在，不须厦屋太渠渠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-3a82d3b9-eef6-48cd-80f2-b8ceae38a439","tags":[]},{"id":"poem-672ce8099bdff5b72a97559a","title":"减字木兰花·卖花担上","author":"李清照","dynasty":"宋","verses":["卖花担上。","买得一枝春欲放。","泪染轻匀。","犹带彤霞晓露痕。","怕郎猜道。","奴面不如花面好。","云鬓斜簪。","徒要教郎比并看。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-718","tags":[]},{"id":"poem-672da000c693ab568a1beeff","title":"临江仙·素洛春光潋滟平","author":"牛希济","dynasty":"五代","verses":["素洛春光潋滟平，千重媚脸初生。","凌波罗袜势轻轻，烟笼日照，珠翠半分明。","风引宝衣疑欲舞，鸾回凤翥堪惊。","也知心许无恐成，陈王辞赋，千载有声名。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-37","tags":[]},{"id":"poem-673f3f69e38b405d89f6615c","title":"瑞鹧鸪·一痕月色挂帘栊","author":"周纯","dynasty":"宋","verses":["一痕月色挂帘栊。","梅影斜斜小院中。","狂醉有心窥粉面，梦魂无处避香风。","愁来梦楚三千里，人在巫山十二重。","咫尺蓝桥无处问，玉萧声断楚山空。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-944","tags":[]},{"id":"poem-67405553c17e22f8aebc41fc","title":"句  其二","author":"鲜于侁","dynasty":"宋","verses":["感公行乐处，蚤莫得相思。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-ad4b6dc4-5f71-4c5c-be1c-9efa6ce7234d","tags":[]},{"id":"poem-674518177bd60a4259ca19c4","title":"仲春有怀  其四","author":"张栻","dynasty":"宋","verses":["楚翠亭边花正开，道乡台下石崔嵬。","主人今有此客否，客亦思君日百回。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-20c5104e-0086-40c8-8ddc-fd635492388d","tags":[]},{"id":"poem-674615538af0bf6acb13480a","title":"滁州西涧","author":"韦应物","dynasty":"唐","verses":["独怜幽草涧边生，上有黄鹂深树鸣。","春潮带雨晚来急，野渡无人舟自横。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-0ae0e3bd-a32e-481f-9719-b283da2da964","tags":["唐诗三百首","春","山水","写景","抒情","初中古诗","七言绝句","水","七年级下册(课外)"]},{"id":"poem-6748aef9bb14752eb0c69704","title":"蜘蛛谕","author":"苏拯","dynasty":"唐","verses":["春蚕吐出丝，济世功不绝。","蜘蛛吐出丝，飞虫成聚血。","蚕丝何专利，尔丝何专孽。","映日张网罗，遮天亦何别。","傥居要地门，害物可堪说。","网成虽福己，网败还祸尔。","小人与君子，利害一如此。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-6c94e69f-461f-46fd-83f6-d4cc44001edf","tags":[]},{"id":"poem-674a4d9bfad76dd2155cc27b","title":"集宿姚侍御宅怀永乐宰殷侍御","author":"马戴","dynasty":"唐","verses":["石田虞芮接，种树白云阴。","穴闭神踪古，河流禹凿深。","樵人应满郭，僊鸟几巢林。","此会偏相语，曾供雪夜吟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-33236907-df1c-4890-984a-099367f1b306","tags":[]},{"id":"poem-675ea0304694be9a36a2b136","title":"所思","author":"张佖","dynasty":"宋","verses":["空塘水碧春雨微，东风散漫杨柳飞。","依依南浦梦犹在，脉脉高唐云不归。","江头日暮多芳草，极目伤心烟悄悄。","隔江红杏一枝明，似玉佳人俯清沼。","休向春台更回望，销魂自古因惆怅。","银河碧海共无情，两处悠悠起风浪。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-5d03e279-0853-4f9c-8b42-a03324f6ea87","tags":[]},{"id":"poem-676c124cf85b10a3462641b2","title":"满江红·一舸归来","author":"游次公","dynasty":"宋","verses":["一舸归来，何太晚、鬓丝如织。","谩叹息、凄凉往事，尽成陈迹。","山迫暮烟浮紫翠，溪摇寒浪翻金碧。","看长虹、渴饮下青冥，危栏湿。","谁可住，烟萝侧。","俗士驾，当回勒。","伴岩扃，须是碧云仙客。","风月已供无尽藏，溪山更衍清凉国。","恨谪仙、苏二不曾来，无人说。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-269","tags":[]},{"id":"poem-6779fa8985d29c864eb10585","title":"奉和颜鲁公真卿落玄真子舴艋舟歌","author":"皎然","dynasty":"唐","verses":["沧浪子后玄真子，冥冥钓隐江之汜。","刳木新成舴艋舟，诸侯落舟自兹始。","得道身不系，无机舟亦闲。","从水远逝兮任风还，朝五湖兮夕三山。","停纶乍入芙蓉浦，击汰时过明月湾。","太公取璜我不取，龙伯钓鼇我不钓。","竹竿袅袅鱼簁簁，此中自得还自笑。","汗漫一游何可期，后来谁遇冰雪姿。","上古初闻出尧世，今朝还见在尧时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-d1631d0a-1ab3-49e4-9b18-b77d538961a5","tags":[]},{"id":"poem-6780466cabbf0ec0c3dbb738","title":"经方干旧居","author":"释干康","dynasty":"宋","verses":["镜湖中有月，处士后无人。","荻笋抽高节，鲈鱼跃老鳞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-4ae99bc1-8875-4ea7-9038-2718c3fcfb75","tags":[]},{"id":"poem-678623393c415b7a6b225cae","title":"自君之出矣","author":"李康成","dynasty":"唐","verses":["自君之出矣，弦吹绝无声。","思君如百草，撩乱逐春生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-157dde0c-9fb0-4ca2-8c33-6f412582c028","tags":[]},{"id":"poem-67868c7846e6f70e93168473","title":"集灵台二首 二","author":"张祜","dynasty":"唐","verses":["虢国夫人承主恩，平明骑马入宫门。","却嫌脂粉汚颜色，淡扫蛾眉朝至尊。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-51262a8c-de53-41ee-958a-de08d5f5a446","tags":["唐诗三百首","写人","七言绝句","讽刺"]},{"id":"poem-6794d60ea034de74bc6cc9ff","title":"送范启东","author":"牟融","dynasty":"唐","verses":["杨柳春江上，东风一櫂轻。","行囊归客兴，尊酒故人情。","画史名当代，声华重两京。","临岐分手处，无奈别离生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-d1e265dd-c04b-4ce7-b253-9c1bd436bcc6","tags":[]},{"id":"poem-67978162dbf16963185ece75","title":"别离情所钟十二章章四句送定叟弟之官严陵  其四","author":"张栻","dynasty":"宋","verses":["我昔临此州，民容拙使君。","子行为多谢，慰彼无毫分。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-f6628928-6a01-4242-a8f2-ed702b9724ff","tags":[]},{"id":"poem-6798837f3b6bea973c6092c6","title":"仙吕/后庭花","author":"杨景贤","dynasty":"元","verses":["我这里收拾下金共银，则要你早分一个冤与恩。","俺孩儿经卷能成事，陈光蕊呵，你说甚文章可立身？莫因循，疾忙前进。","下水船风力稳，报仇心如箭紧，去程忙似火焚。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-7965","tags":[]},{"id":"poem-67abdf9f0782f9edd3584495","title":"捣练子·云鬓乱","author":"李煜","dynasty":"五代","verses":["云鬓乱，晚妆残，带恨眉儿远岫攒。","斜托香腮春笋嫩，为谁和泪倚栏杆。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-42","tags":[]},{"id":"poem-67bb4b11c861bc624d3d8ae2","title":"前腔","author":"徐田臣《杀狗记》","dynasty":"元","verses":["兄弟怡怡乐有余，终日里玩史攻书。","十载辛勤，一朝遭际，不负家传豪贵。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1691","tags":[]},{"id":"poem-67bfa66780935a72ead305ca","title":"闲","author":"徐夤","dynasty":"唐","verses":["不管人间是与非，白云流水自相依。","一瓢挂树傲时代，五柳种门吟落晖。","江上翠娥遗佩去，岸边红袖采莲归。","客星辞得汉光武，却坐东江旧藓矶。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-dfb2efa4-daf5-4fc9-950f-44e74f85e0dd","tags":[]},{"id":"poem-67c1231923f63e11bb72aee4","title":"又代孔明哭先主","author":"李山甫","dynasty":"唐","verses":["鲸鬣翻腾四海波，始将天意用干戈。","尽驱神鬼随鞭策，全罩英雄入网罗。","提劒尚残吴郡国，垂衣犹欠魏山河。","鼎湖无路追仙驾，空使群臣泣血多。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-98c46436-ea84-44e4-8521-825a69e01082","tags":[]},{"id":"poem-67c24cf79a8ef00a8debfd49","title":"插田","author":"释居简","dynasty":"宋","verses":["秧撒才成后，沟塍莅事初。","浅车防岸缺，密插趁行疎。","处处隣相馌，乔乔莠旋除。","夕阳归牧竖，牛背数舂鉏。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-fc39a5ff-46f4-43b8-ba66-6c14ea4b5d40","tags":[]},{"id":"poem-67c3b7a55663c0f7cdc91ace","title":"颂古三十一首  其一○","author":"释安永","dynasty":"宋","verses":["不放溪东西，随分纳些儿。","冷暖只自知，分明说向谁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-cfe64923-c032-4303-b333-d4fdb580be57","tags":[]},{"id":"poem-67c89c99ae48cc670b656324","title":"喜迁莺·晓月坠","author":"李煜","dynasty":"五代","verses":["晓月坠，宿烟微，无语枕频倾攲。","梦回芳草思依依，天远雁声稀。","啼莺散，馀花乱，寂寞画堂深院。","片红休扫尽从伊，留待舞人归。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-13","tags":[]},{"id":"poem-67d24bcf646666545caaf3a5","title":"赠龙兴观主吴崇岳","author":"周渭","dynasty":"唐","verses":["楮为冠子布为裳，吞得丹霞寿最长。","混俗性灵常乐道，出尘风格早休粮。","枕中经妙谁传与，肘后方新自写将。","百尺松梢几飞步，鹤栖板上礼虚皇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-022a1d72-1028-493e-897e-42b6cdb47e84","tags":[]},{"id":"poem-67d3836058ebdc01697ace15","title":"叨叨令","author":"杨景贤","dynasty":"元","verses":["有时俯视溪流看，更险似单骑羸马连云栈。","一声鹤唳青松涧，更惨似琵琶声里君恩断。","兀的不闷杀人也么哥，兀的不闷杀人也么哥。","几时能勾一杯末尽笙歌散。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4517","tags":[]},{"id":"poem-67dbe8bdc603c8dc3ca87e24","title":"寄乌龙山贾泰处士","author":"贯休","dynasty":"唐","verses":["庭果色如丹，相思夕照残。","云边踏烧去，月下把书看。","涧水仙居共，窗风漆树寒。","吾君方侧席，未可便怀安。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-086f8ae0-fcf0-4896-a691-940c0ed9af92","tags":[]},{"id":"poem-67e2cce6558113f0901f5567","title":"简云卧","author":"赵崇鉘","dynasty":"宋","verses":["忆君心事如流水，流向江头作暮潮。","想得潮平沙有雪，自铿铁版和吹箫。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-a27180ea-b9a4-469d-87b3-758ff4ae40a1","tags":[]},{"id":"poem-67e3dd81ea164589128dae36","title":"永明山居诗（六十九首） 二十二","author":"延寿","dynasty":"唐","verses":["且停多事莫矜夸，寂寞门中有道华。","隈岭静同猿窟宅，栽松闲共鹤生涯。","荣来只爱添余录禄，春过谁能悟落花。","唯有卧云尘外客，无思无虑老烟霞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-2c6a3b05-ad48-4615-b3b1-0bc735735cbd","tags":[]},{"id":"poem-67e6a5b0a7730b2bae75a37d","title":"郊庙歌辞 襃德庙乐章 昭德","author":"不详","dynasty":"唐","verses":["道赫梧宫，悲盈蒿里。","爰赐徽烈，载敷嘉祀。","享洽四时，规陈二簋。","灵应昭格，神其戾止。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-cc360c8a-07ac-45e0-bd96-bf2e8dfba5da","tags":[]},{"id":"poem-67eb20cb9b5d63914163a6ff","title":"三月过行宫","author":"李贺","dynasty":"唐","verses":["渠水红繁拥御墙，风娇小叶学娥妆。","垂帘几度青春老，堪锁千年白日长。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-350ee905-ef68-43ab-9fd0-8e670cd02bff","tags":["遭遇","写人","抒怀","写景","写人诗"]},{"id":"poem-67f3606cd166d5d27bdc2759","title":"巧言","author":"佚名","dynasty":"先秦","verses":["悠悠昊天，曰父母且。无罪无辜，乱如此幠。昊天已威，予慎无罪。昊天大幠，予慎无辜。","乱之初生，僭始既涵。乱之又生，君子信谗。君子如怒，乱庶遄沮。君子如祉，乱庶遄已。","君子屡盟，乱是用长。君子信盗，乱是用暴。盗言孔甘，乱是用餤。匪其止共，维王之邛。","奕奕寝庙，君子作之。秩秩大猷，圣人莫之。他人有心，予忖度之。跃跃毚兔，遇犬获之。","荏染柔木，君子树之。往来行言，心焉数之。蛇蛇硕言，出自口矣。巧言如簧，颜之厚矣。","彼何人斯？居河之麋。无拳无勇，职为乱阶。既微且尰，尔勇伊何？为犹将多，尔居徒几何？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-197","tags":[]},{"id":"poem-67fbd79d119769a77ab2780d","title":"赋得灯心送李侍御萼","author":"皎然","dynasty":"唐","verses":["灯心生众草，因有始知芳。","彩妓窗偏丽，金桃动更香。","花惊春未尽，焰喜夜初长。","别后空离室，何人借末光。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-0a9f435e-e8c4-45c1-b7a2-e1244e002fa4","tags":[]},{"id":"poem-67fe011668a409bf4600845a","title":"咏马鞭","author":"高适","dynasty":"唐","verses":["龙竹养根凡几年，工人截之为长鞭。","一节一目皆天然，珠重重，星连连。","绕指柔，纯金坚，绳不直，规不圆。","把向空中捎一声，良马有心日驰千。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-b7c8a7fe-7ad4-44fe-9b71-3c085eb5e999","tags":[]},{"id":"poem-6809de41b7816dd69aab855a","title":"边上作三首 三","author":"贯休","dynasty":"唐","verses":["见说青冢穴，中有白野狐。","时时出沙碛，向东而号呼。","号呼复号呼，画师图得无。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-af42490e-26c5-4b68-8103-532d4fc6744f","tags":[]},{"id":"poem-680d94f5e406a17fae4b74f3","title":"移疾","author":"张载","dynasty":"宋","verses":["移疾谢华省，问耕还弊舍。","扶持便疏慵，旷僻逃将迓。","昼棋莎径侧，暮粥梧阴下。","久矣澄清心，永愧桑弧射。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-4e7ee02c-2b4b-4ac4-ab9b-0f8359a3af58","tags":[]},{"id":"poem-680dea4c5e6be63ef208e156","title":"送僧二首 一","author":"马戴","dynasty":"唐","verses":["亲在平阳忆久归，洪河雨涨出关迟。","独过旧寺人稀识，一一杉松老别时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-15f0943a-4211-41e1-b830-a3b493048f96","tags":[]},{"id":"poem-681073458b594f19079ec250","title":"鼓吹曲辞 巫山高二首 一","author":"孟郊","dynasty":"唐","verses":["巴山上峡重复重，阳台碧峭十二峰。","荆王猎时逢暮雨，夜卧高丘梦神女。","轻红流烟湿艳姿，行云飞去明星稀。","目极魂断望不见，猨啼三声泪沾衣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-df99dd63-0832-4715-8e63-ce89452560a1","tags":["写山","传说","写景","描写山"]},{"id":"poem-681f8dcabd6417dd33804905","title":"春晴","author":"史卫卿","dynasty":"宋","verses":["平明晴可爱，眼界一湖春。","不见水中鹭，惟多堤上人。","梅花已白尽，柳色正青新。","日暮无歌舞，清幽属野身。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-b64bf08f-68a9-49af-a5c8-6f831b6930c5","tags":[]},{"id":"poem-682468327e8c7c404d6d97e8","title":"赤谷西崦人家","author":"杜甫","dynasty":"唐","verses":["跻险不自喧，出郊已清目。","溪回日气暖，径转山田熟。","鸟雀依茅茨，藩篱带松菊。","如行武陵暮，欲问桃花宿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-2b104baa-0304-4ae1-944c-c766ace60ec1","tags":[]},{"id":"poem-6825f8e973d22514b7d481af","title":"送崔融","author":"杜审言","dynasty":"唐","verses":["君王行出将，书记远从征。","祖帐连河阙，军麾动洛城。","旌旗朝朔气，笳吹夜边声。","坐觉烟尘少，秋风古北平。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-送崔融","tags":[]},{"id":"poem-683070c4e2ec3d993c6801e8","title":"诉衷情·银汉云晴玉漏长","author":"魏承班","dynasty":"五代","verses":["银汉云晴玉漏长，蛩声悄画堂。","筠簟冷，碧窗凉，红蜡泪飘香。","皓月泻寒光，割人肠。","那堪独自步池塘，对鸳鸯。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-6","tags":[]},{"id":"poem-68329d0c43f66d5bcaa12245","title":"将别寄友人","author":"马戴","dynasty":"唐","verses":["帝乡归未得，辛苦事羇游。","别馆一尊酒，客程千里秋。","霜风红叶寺，夜雨白苹洲。","长恐此时泪，不禁和恨流。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-dc7ad1fe-4b03-4e4a-8b03-c1ae0841c11b","tags":[]},{"id":"poem-683fcf6006ee90dfa717ff9c","title":"倦寻芳慢・倦寻芳·露晞向晚","author":"王","dynasty":"宋","verses":["露晞向晚，帘幕风轻，小院闲昼。","翠迳莺来，惊下乱红铺绣。","倚危墙，登高榭，海棠经雨胭脂透。","算韶华，又因循过了，清明时候。","倦游燕、风光满目，好景良辰，谁共携手。","恨被榆钱，买断两眉长斗。","忆高阳，人散后。","落花流水仍依旧。","这情怀，对东风、尽成消瘦。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-642","tags":[]},{"id":"poem-6845fa5e19b1fe129aa4aa02","title":"僧院蔷薇","author":"李咸用","dynasty":"唐","verses":["客引擎茶看，离披晒锦红。","不缘开净域，争忍负春风。","小片当吟落，清香入定空。","何人来此植，应固恼休公。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-5d1ebc13-f6cf-4907-bed4-e0a19a60731f","tags":[]},{"id":"poem-68471c6b4d5e3d6cc74b353b","title":"汀州定光南安岩诗二首（题拟） 一","author":"郑元弼","dynasty":"唐","verses":["石耸灵岩接太虚，百千年称定光居。","未知天上何方有，应是人间别地无。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-6ab487b7-eb13-49f5-9e1a-8cc6e36ef10d","tags":[]},{"id":"poem-684abe382db06b50977672f7","title":"奉纪","author":"綦崇礼","dynasty":"宋","verses":["八座近黄扉，三公宜黑发。","用舍岂自谋，机缄何翕忽。","一麾遽出守，双溪厌风月。","江海今就闲，议论犹英发。","大厦终须材，虚舟聊应物。","胜览莫辞频，君驺宁久歇。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-d4e4452f-0bed-414c-b9b0-858a0e1fdbc2","tags":[]},{"id":"poem-68539676e3f5ab4b89dfd10a","title":"瑞鹤仙令・临江仙·樱桃落尽春归去","author":"康与之","dynasty":"宋","verses":["樱桃落尽春归去，蝶翻金粉双飞。","子规啼恨小楼西。","曲屏珠箔晚，惆怅卷金泥。","门巷寂寥人去后，望残烟草低迷。","闲寻旧曲玉笙悲。","关山千里恨，云汉月重规。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-316","tags":[]},{"id":"poem-685514d6436ae6b0018e6f6a","title":"渔家傲·九日欢游何处好","author":"欧阳修","dynasty":"宋","verses":["九日欢游何处好。","黄花万蕊雕阑绕。","通体清香无俗调。","天气好。","烟滋露结功多少。","日脚清寒高下照。","宝钉密缀圆斜小。","落叶西园风袅袅。","催秋老。","丛边莫厌金尊倒。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-662","tags":[]},{"id":"poem-685588807d2187e4ed3b3ac3","title":"和清明后一日游西池","author":"苏颂","dynasty":"宋","verses":["万家供帐集西明，彩舰芳林酒屡行。","强对鶑花无奈老，时闻歌吹不胜情。","轮囷佳气城头近，烋噢清风语下生。","休沐傥闲须数往，水边庭际解朝缨。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-18796fb7-1cf7-4c2c-b2f0-dc02a108e786","tags":[]},{"id":"poem-68573b69dd28876597322a37","title":"春过函谷关","author":"于邺","dynasty":"唐","verses":["几度作游客，客行长苦辛。","愁看函谷路，老尽布衣人。","岁远关犹固，时移草亦春。","何当名利息，遣此绝征轮。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-63cdd33b-74f3-464a-b3f4-50d562835157","tags":[]},{"id":"poem-6859a6d3da5b2a1d217a6bb8","title":"观雨","author":"王同祖","dynasty":"宋","verses":["萧萧疏雨逐斜风，三两归鸦暮霭中。","看到菊花无可看，一年秋事又成空。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-d25adb22-dd86-4ee8-97fd-a33fac3f761b","tags":[]},{"id":"poem-68649e27e02edd4002617145","title":"次韵徐秀才十首  其六","author":"陈造","dynasty":"宋","verses":["霄霏上冥鸿，山雾卧文豹。","饿鸱吓腐鼠，啄啄诧飞趠。","吾徒为己学，欣戚置不校。","小草或远志，诡遇乃近效。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-53c2cd4d-e508-4c8a-864b-afcfff413b1c","tags":[]},{"id":"poem-686d5c9125029c3558f4166a","title":"腊月二十二日渡湘登道乡台夜归得五绝  其二","author":"张栻","dynasty":"宋","verses":["旧日书堂倚翠屏，只今栋宇尚高明。","门前恍若闻弦诵，㶁㶁遶墙流水声。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-a41c9906-f894-4af4-bcba-c00be0594a18","tags":[]},{"id":"poem-68704c23daf702b4f63493e2","title":"思远人","author":"王建","dynasty":"唐","verses":["妾思常悬悬，君行复绵绵。","征途向何处，碧海与青天。","岁久自有念，谁令长在边。","少年若不归，兰室如黄泉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-fed7bba3-9372-4ffb-bce2-5733cb757be5","tags":[]},{"id":"poem-687346350918e08bf0ecef61","title":"鼓吹曲辞 鼓吹铙歌 高昌","author":"柳宗元","dynasty":"唐","verses":["曲氏雄西北，别绝臣外区。","既恃远且险，纵傲不我虞。","烈烈王者师，熊螭以为徒。","龙旗飜海浪，驲骑驰坤隅。","贲育搏婴儿，一扫不复余。","平沙际天极，但见黄云驱。","臣靖执长缨，智勇伏囚拘。","文皇南面坐，夷狄千群趋。","咸称天子神，往古不得俱。","献号天可汗，以覆我国都。","兵戎不交害，各保性与躯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-f9acb857-f038-4a86-a5a5-8a3266306b8e","tags":[]},{"id":"poem-68803ed68de6ec132ed78c3c","title":"吴氏新城宅","author":"陈岩","dynasty":"宋","verses":["溪声西去疾于雷，山麓云根翠户开。","枉却幽寻三十载，壶天月窟欠曾来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-02493dcc-294b-4eb3-8cc7-8250c095b86c","tags":[]},{"id":"poem-68829271a39edb09e2fbbe7a","title":"独立","author":"赵崇嶓","dynasty":"宋","verses":["片云收雨入西山，望极苍茫杳霭间。","荡荡太虚无一事，祗应日月不曾闲。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-f7165bd6-bf25-41a5-a7eb-4603bbad4a9f","tags":[]},{"id":"poem-6882f9e4bbc99d73d1685925","title":"思君恩","author":"令狐楚","dynasty":"唐","verses":["小苑莺歌歇，长门蝶舞多。","眼看春又去，翠辇不曾过。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-思君恩","tags":[]},{"id":"poem-6886da38856b34a62bce268f","title":"如梦令·万帐穹庐人醉","author":"纳兰性德","dynasty":"清","verses":["万帐穹庐人醉，星影摇摇欲坠，归梦隔狼河，又被河声搅碎。","还睡、还睡，解道醒来无味。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-54","tags":[]},{"id":"poem-688a07fec8308e7ab082c6b2","title":"次韵折仲古安抚端明食荔子感怀书事之作","author":"李纲","dynasty":"宋","verses":["卧病闽山强自支，尝珍似与故人期。","却嗟老眼伤心日，又见轻红着子时。","万事从来皆默定，一樽聊复赋新诗。","使君不作楞梨看，他日逢人举似为。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-9a42b502-a6a9-48e0-b300-4fb8750ee11c","tags":[]},{"id":"poem-688f18395594725a7d15c32f","title":"早发白帝城","author":"李白","dynasty":"唐","verses":["朝辞白帝彩云间，千里江陵一日还。","两岸猨声啼不尽，轻舟已过万重山。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-9525f99d-39cb-4d04-8650-263493d223e0","tags":["唐诗三百首","长江","山","喜悦","七言绝句","描写山","写山","带有地名","地名"]},{"id":"poem-689270058fafd9b71a4ed248","title":"杂曲歌辞 盖罗缝 一","author":"不详","dynasty":"唐","verses":["秦时明月汉时关，万里征人尚未还。","但愿龙庭神将在，不教胡马渡阴山。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-7066e611-faa5-427c-8fce-e0bf10c55416","tags":["战争","写景","忧国忧民","爱国","唐诗三百首","乐府","山","边塞"]},{"id":"poem-6899241faa73a1fc47cd0603","title":"楚茨","author":"佚名","dynasty":"先秦","verses":["楚楚者茨，言抽其棘，自昔何为？我蓺黍稷。我黍与与，我稷翼翼。","我仓既盈，我庾维亿。以为酒食，以享以祀，以妥以侑，以介景福。","济济跄跄，絜尔牛羊，以往烝尝。或剥或亨，或四或将。祝祭于祊，祀事孔明。先祖是皇，神保是飨。孝孙有庆，报以介福，万寿无疆！","执爨踖踖，为俎孔硕，或燔或炙。君妇莫莫，为豆孔庶。为宾为客，献酬交错。礼仪卒度，笑语卒获。神保是格，报以介福，万寿攸酢！","我孔戁矣，式礼莫愆。工祝致告，徂赉孝孙。苾芬孝祀，神嗜饮食。","卜尔百福，如几如式。既齐既稷，既匡既敕。永锡尔极，时万时亿！","礼仪既备，钟鼓既戒，孝孙徂位，工祝致告，神具醉止，皇尸载起。","鼓钟送尸，神保聿归。诸宰君妇，废彻不迟。诸父兄弟，备言燕私。","乐具入奏，以绥后禄。尔肴既将，莫怨具庆。既醉既饱，小大稽首。","神嗜饮食，使君寿考。孔惠孔时，维其尽之。子子孙孙，勿替引之！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-208","tags":[]},{"id":"poem-68a78616a3b350d6d278581d","title":"信行远修水筒","author":"杜甫","dynasty":"唐","verses":["汝性不茹荤，清静仆夫内。","秉心识本源，于事少滞碍。","云端水筒坼，林表山石碎。","触热藉子修，通流与厨会。","往来四十里，荒险崖谷大。","日熏惊未餐，貌赤媿相对。","浮瓜供老病，裂饼尝所爱。","于斯荅恭谨，足以殊殿最。","讵要方士符，何假将军盖。","行诸直如笔，用意崎岖外。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-3eef1d5f-2011-4417-be2c-57667aa3bea6","tags":[]},{"id":"poem-68ad9a8eb7f556a4a37b2b0e","title":"闰月九日登越王台次韵经略敷文所寄诗","author":"林光朝","dynasty":"宋","verses":["闲陪小队出山椒，为有吴歌杂楚谣。","纵道菊花如昨日，要看汤饼作三朝。","千重岭海供横槊，一带风烟听采樵。","凭仗折冲如此好，不应东去更乘轺。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-ac710ca8-f8ba-4ebd-aaf6-f5a5037adb2e","tags":[]},{"id":"poem-68b13e4d69dd53ffea768fd0","title":"送岳州司马弟之任","author":"李嘉祐","dynasty":"唐","verses":["岳阳天水外，念尔一帆过。","野墅人烟逈，山城雁影多。","有时巫峡色，终日洞庭波。","丞相今为郡，应无劳者歌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-ccd8a969-3713-4066-b890-ead4d4fb7b6e","tags":["洞庭湖"]},{"id":"poem-68c7a925955a37f0188fa7a2","title":"循吏曲上王使君","author":"贯休","dynasty":"唐","verses":["需宿需宿，炳烂光合。","蒸蒸婺民，钟此多福。","自东自西，自南自北。","伊飞伊走，乳乳良牧。","和气无形，春光自成。","大信不信，贻厥无朕。","需女需女，尔亦须语。","使君为理，玄风震古。","需女需女，尔亦须语。","我愿喙长三千里，枕著玉阶奏明主。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-aeb4697e-c3da-4a14-8cbe-f96eff2ba28f","tags":[]},{"id":"poem-68cd1bc628c55438d31ca3a0","title":"读张曲江集","author":"皎然","dynasty":"唐","verses":["相公乃天盖，人文佐生成。","立程正颓靡，绎思何纵横。","春杼弄缃绮，阳林敷玉英。","飘然飞动姿，邈矣高简情。","后辈惊失步，前修敢争衡。","始欣耳目远，再使机虑清。","体正力已全，理精识何妙。","昔年歌阳春，徒推郢中调。","今朝听鸾凤，岂独羡门啸。","帝命镇雄州，待济寄上流。","才兼荆衡秀，气助潇湘秋。","逸荡子山匹，经奇文畅俦。","沈吟未终卷，变态纷难数。","曜耳代明珰，袭衣同芳杜。","愔愔闻玉磬，寤寐在灵府。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-4ff6d91f-2f0b-403e-be77-1763e842d62f","tags":[]},{"id":"poem-68d560af3c21fcb1c701bab6","title":"兵要望江南 占梦第二十五（京本列第十三○九首） 八","author":"易静","dynasty":"唐","verses":["将军梦，身涉大高山。","遇战必赢功显著，相逢敌战（京本作「鬬敌」）急攻残，莫放片时间。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-4cd9d85f-2955-40e5-8391-1ed40da76e9f","tags":[]},{"id":"poem-68d73834e5d8856d10b695d6","title":"送魏季羔游长沙觐兄","author":"司空曙","dynasty":"唐","verses":["芦荻湘江水，萧萧万里秋。","鹤高看迥野，蝉远入中流。","访友多成滞，携家不厌游。","惠连仍有作，知得从兄酬。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-8095147b-d6cc-449c-9b3b-02996f626e1f","tags":[]},{"id":"poem-68d7fbbc19b35fdd5d2e9538","title":"句  其五","author":"林迥","dynasty":"宋","verses":["过门人指朝郎宅，入室浑如野老家。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-cbf27fc1-4f5e-4b39-b67d-afa8fde57f28","tags":[]},{"id":"poem-68dd77eef3af5a9918ab23d3","title":"郊庙歌辞 明皇祀圜丘乐章 寿和","author":"不详","dynasty":"唐","verses":["六变爰阕，八阶载虔。","祐我皇祚，于万斯年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-6bb0f308-c254-4a99-9204-638f271b76cd","tags":[]},{"id":"poem-68e1149d58c1c1bcfac6d623","title":"杏殇 三","author":"孟郊","dynasty":"唐","verses":["应是一线泪，入此春木心。","枝枝不成花，片片落翦金。","春寿何可长，霜哀亦已深。","常时洗芳泉，此日洗泪襟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-3cd29e60-6971-4072-8a0e-8d96adefe284","tags":[]},{"id":"poem-68e3ca19c8ce8a6ccdedf110","title":"偈颂六首 五","author":"神晏","dynasty":"唐","verses":["白云长满洞，论劫未曾亏。","不话曹溪旨，焉干道者机。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-d5e264cd-4a48-415a-a255-1401006cfb26","tags":[]},{"id":"poem-68f049357d23e0e4e602aa3a","title":"郊庙歌辞 梁太庙乐舞辞 送神","author":"不详","dynasty":"唐","verses":["其降无从，其往无踪。","黍稷非馨，有感必通。","赫奕令德，髣髴睟容。","再拜慌忽，遐想昊穹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-54a1868d-5896-4ede-81ee-9793077ce6a2","tags":[]},{"id":"poem-68f44cf155abcb911ceb9115","title":"思平泉树石杂咏一十首 海鱼骨","author":"李德裕","dynasty":"唐","verses":["昔日任公子，期年钓此鱼。","无由见成岳，聊喜识专车。","皎皎连霜月，高高映碧渠。","陶潜虽好事，观海只披图。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-b2afed80-f205-46c2-9c85-70ed40845509","tags":[]},{"id":"poem-68f9ebd211b4feb492d7ee63","title":"浪淘沙·休看辋川图","author":"葛立方","dynasty":"宋","verses":["休看辋川图。","未是幽居。","何如云水绕储胥。","新湿青红开栋宇，雾拱风疏。","小圃秀郊墟。","花破平芜。","五峰列影水平铺。","只欠五城楼十二，便是蓬壶。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-534","tags":[]},{"id":"poem-68fd3d922164c4d2e2c8bf1b","title":"奉和仆射相公送东川李支使归使府夏侯相公","author":"薛逢","dynasty":"唐","verses":["两地交通布政和，上台深喜使星过。","欢留白日千钟酒，调入青云一曲歌。","寒柳翠添微雨重，腊梅香绽细枝多。","平津万一言卑散，莫忘高松寄女萝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-35efc93b-b880-4dd2-9414-0e33c08ea56f","tags":[]},{"id":"poem-6906a136f3e14a89f5b3a1f7","title":"江湖秋思","author":"李嘉祐","dynasty":"唐","verses":["趋陪禁掖鴈行随，迁向江潭鹤发垂。","素浪遥疑八谿水，清枫忽似万年枝。","嵩南春徧伤魂梦，壶口云深隔路岐。","共望汉朝多霈泽，苍蝇早晚得先知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-3007f5f4-1d3c-4960-9e74-d75729d8fe3a","tags":[]},{"id":"poem-69078e3ab632ec26475b892e","title":"挂真儿","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［老旦上］天付姻缘事谐矣，夫和妇如鱼似水。","［生上］贫处蜗居，羞婚燕尔，惟恐旁人谈耻。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8115","tags":[]},{"id":"poem-6909f5360422ceab36c8ea18","title":"清平乐·东风桂影","author":"毛滂","dynasty":"宋","verses":["东风桂影。","低拂姮娥镜。","镜里妆寒酥粉莹。","越恁十分端正。","素光行处随人。","柳边照见青春。","一片笙箫何处，花阴定有遗簪。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-716","tags":[]},{"id":"poem-690e42b2c3279a2843a73940","title":"河渎神·古树噪寒鸦","author":"张泌","dynasty":"五代","verses":["古树噪寒鸦，满庭枫叶芦花。","昼灯当午隔轻纱，画阁珠帘影斜。","门外往来祈赛客，翩翩帆落天涯。","回首隔江烟火，渡头三两人家。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-2","tags":[]},{"id":"poem-6915e46cf3febeba4e08c2fb","title":"物情","author":"李咸用","dynasty":"唐","verses":["谁分万类二仪间，禀性高卑各自然。","野鹤不栖葱蒨树，流莺长喜艳阳天。","李斯溷鼠心应动，庄叟泥龟意已坚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-0666b456-7af2-4b9e-b1e4-9f5413adbd8f","tags":[]},{"id":"poem-69188cfcadf1a4dfa2c0d567","title":"绣鸾凤花犯・花犯·楚江湄","author":"周密","dynasty":"宋","verses":["楚江湄，湘娥乍见，无言洒清泪。","淡然春意。","空独倚东风，芳思谁寄。","凌波路冷秋无际。","香云随步起。","谩记得，汉宫仙掌，亭亭明月底。","冰弦写怨更多情，骚人恨，枉赋芳兰幽芷。","春思远，谁叹赏、国香风味。","相将共、岁寒伴侣。","小窗净、沈烟熏翠袂。","幽梦觉，涓涓清露，一枝灯影里。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-93","tags":["宋词三百首"]},{"id":"poem-691aec0e1f97795699f18dfd","title":"日月","author":"佚名","dynasty":"先秦","verses":["日居月诸，照临下土。乃如之人兮，逝不古处？胡能有定？宁不我顾。","日居月诸，下土是冒。乃如之人兮，逝不相好。胡能有定？宁不我报。","日居月诸，出自东方。乃如之人兮，德音无良。胡能有定？俾也可忘。","日居月诸，东方自出。父兮母兮，畜我不卒。胡能有定？报我不述。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-28","tags":[]},{"id":"poem-691d1346882b5c4d955615bc","title":"颜提举之官","author":"释居简","dynasty":"宋","verses":["兰陵曾颂隣州政，除却龚黄总不如。","又似澄江千尺练，只传陋巷一编书。","坐令季子昌遗俗，尽道丹山更好雏。","老我林泉散樗栎，守愚终不与贤疎。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-6e8b3921-2d80-478e-8105-668bc71de66f","tags":[]},{"id":"poem-69245d7ab4ef95c9f63940d6","title":"及第后呈朝中知己","author":"李旭","dynasty":"唐","verses":["凌晨晓鼓奏嘉音，雷拥龙迎出陆沈。","金榜高悬当玉阙，锦衣即著到家林。","真珠每被尘泥陷，病鹤多遭蝼蚁侵。","今日始知天有意，还教雪得一生心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-90203085-be1b-4eff-a131-8375081baed1","tags":[]},{"id":"poem-69299dd7802099978f320ce0","title":"冬行三首 一","author":"卢仝","dynasty":"唐","verses":["虫豸腊月皆在蛰，吾独何乃劳其形。","小大无由知天命，但怪守道不得宁。","老母妻子一挥手，涕下便作千里行。","自顾不及遭霜叶，旦夕保得同飘零。","达生何足云，偶然苦乐经其身。","古来尧孔与桀跖，善恶何补如今人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-6fac0cea-b4ee-419b-9802-786d508141f9","tags":[]},{"id":"poem-692b01786f945e7cea477830","title":"苕溪新上人石窗","author":"释居简","dynasty":"宋","verses":["太白岩空夜弗扃，好风不约满疏櫺。","旧题寂寞无人管，散作苕溪水上云。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-96ae233c-8cac-44e2-a025-1f3cc45f7f72","tags":[]},{"id":"poem-693f5f797501ead4321f21cc","title":"临江仙·干吕青云垂宝露","author":"洪适","dynasty":"宋","verses":["干吕青云垂宝露，结邻恰挂初弦。","瑞光腾踊杂非烟。","骑箕瞻鼻祖，孕昴控胎仙。","勋业子卿全汉节，壮怀久寄林泉。","举觞低唱脸舒莲。","寿高人七十，果熟岁三千。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-702","tags":[]},{"id":"poem-693fbb213bf6dfb105509269","title":"洞仙歌·青烟幂处","author":"晁补之","dynasty":"宋","verses":["青烟幂处，碧海飞金镜。","永夜闲阶卧桂影。","露凉时、零乱多少寒，神京远，惟有蓝桥路近。","水晶帘不下，云母屏开，冷浸佳人淡脂粉。","待都将许多明，付与金尊，投晓共、流霞倾尽。","更携取、胡床上南楼，看玉做人间，素秋千倾。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-222","tags":["宋词三百首"]},{"id":"poem-69446933245227f57a8ce9cc","title":"鹡鸰颂","author":"明皇帝","dynasty":"唐","verses":["伊我轩宫，奇树青葱。","蔼周庐兮，冒霜停雪，以茂以悦。","恣卷舒兮，连枝同荣，吐绿含英。","曜春初兮，蓐收御节，寒露微结。","气清虚兮，桂宫兰殿，唯所息宴。","栖雍渠兮，行摇飞鸣，急难有情。","情有余兮，顾惟德凉，夙夜兢惶。","慙化疎兮，上之所教，下之所效。","实在予兮，天伦之性，鲁卫分政。","亲贤居兮，爰游爰处，爰笑爰语。","巡庭除兮，观此翔禽，以悦我心，良史书兮。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-e455ec15-d04b-4797-8a01-da7fa5a5c367","tags":[]},{"id":"poem-6962458a63993f0a2d601cbb","title":"山中四威仪供佛鉴师翁韵  其四","author":"释原妙","dynasty":"宋","verses":["山中卧，月落猿啼过。","正堪眠，石定从教破。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-d8ade8f4-7767-4501-a7d4-cb65274abf43","tags":[]},{"id":"poem-6969d9a22b931b2405a9130c","title":"汤泉应制·鱼鳞雁齿镜中开","author":"纳兰性德","dynasty":"清","verses":["鱼鳞雁齿镜中开，溅沫为霖遍九垓。","不用劫灰求仿佛，便从天汉象昭回。","桑坛法驾乘春转，鹤禁仙镳问寝来。","遥祝海隅同帝泽，年年长听属车雷。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-237","tags":[]},{"id":"poem-69769860447e7397bacbb2ee","title":"郊庙歌辞 周郊祀乐章 感顺乐","author":"不详","dynasty":"唐","verses":["明君陈大礼，展币祀圆丘。","雅乐声其发，祥云色正浮。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-8c45a628-700b-4822-80b5-01cff6f7997b","tags":[]},{"id":"poem-6978e41738553136be835412","title":"频于梦中作宫词何也漫成一首","author":"米芾","dynasty":"宋","verses":["满院红芳减复添，清微风细入重帘。","秾香不使朝醒快，竟日蛮沉拥绣衫。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-d9fbfb8a-bda3-43a2-bb1c-b2a79fb36118","tags":[]},{"id":"poem-697982f490befea291b46677","title":"悼范摅处士","author":"李咸用","dynasty":"唐","verses":["家在五云溪畔住，身游巫峡作闲人。","安车未至柴关外，片玉已藏坟土新。","虽有公卿闻姓字，惜无知己脱风尘。","到头积善成何事，天地茫茫秋又春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-af3091ce-59cc-44a4-ba92-8673a114b33a","tags":[]},{"id":"poem-698a805d6c33c5d81b2f183b","title":"君子偕老","author":"佚名","dynasty":"先秦","verses":["君子偕老，副笄六珈。委委佗佗，如山如河，象服是宜。子之不淑，云如之何？","玼兮玼兮，其之翟也。鬒发如云，不屑髢也。玉之瑱也，象之揥也，扬且之晳也。胡然而天也！胡然而帝也。","瑳兮瑳兮，其之展也。蒙彼绉𫄨，是绁袢也。子之清扬，扬且之颜也。展如之人兮，邦之媛也！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-46","tags":[]},{"id":"poem-698c9e59fbdccddfe459c1de","title":"养竹诗","author":"华镇","dynasty":"宋","verses":["莫笑青青一两茎，春来次第满林生。","露凝节目犹含粉，风过枝梢已有声。","拂拭且看霜雪干，剪裁当见凤凰鸣。","繁枝去尽生微迳，几为清阴特地行。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-b34fbe77-9ab4-45ee-a35e-759bd726a9f5","tags":[]},{"id":"poem-698daef6a2062b58dc0f394d","title":"嘉兴社日","author":"刘言史","dynasty":"唐","verses":["消渴天涯寄病身，临邛知我是何人。","今年社日分余肉，不值陈平又不均。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-4cdb17fe-03cc-49ec-8165-88d4fdca1566","tags":[]},{"id":"poem-69996a54292c7e0b0e970c4e","title":"送若讷上人归衢州","author":"苏颂","dynasty":"宋","verses":["应供何来此，囊书谒紫宸。","清闲频赐对，止观久谈真。","恳谢兰袍宠，恩颁宝字新。","重还乡寺日，学侣益归亲。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-9fd27908-6da1-4b89-a343-70684b1ff3d3","tags":[]},{"id":"poem-699a1f7fcdf86b3c342b003d","title":"开元观","author":"陈岩","dynasty":"宋","verses":["坏道哀湍鬼火青，山间留得观冲名。","仙宫分置玄真像，想见开元旧太平。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-8e594e9a-5cc7-40ad-889d-5b1019c3b0f6","tags":[]},{"id":"poem-69a21b25a738bf66599827a0","title":"遣悲怀三首 一","author":"元稹","dynasty":"唐","verses":["谢公最小偏怜女，嫁与黔娄百事乖。","顾我无衣搜画箧，泥他沽酒拔金钗。","野蔬充膳甘长藿，落叶添薪仰古槐。","今日俸钱过十万，与君营奠复营斋。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-8b57e03d-6d1f-4a4a-ba34-1f58e2551ca1","tags":["唐诗三百首","七言律诗","悼亡"]},{"id":"poem-69a49010d408d3afbf7139fd","title":"朝中措·雕车南陌碾香尘","author":"曾觌","dynasty":"宋","verses":["雕车南陌碾香尘。","一梦尚如新。","回首旧游何在，柳烟花雾迷春。","如今霜鬓，愁停短棹，懒傍清尊。","二十四桥风月，寻思只有消魂。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-403","tags":[]},{"id":"poem-69a4b76075009f5b5b2dcf93","title":"黍离","author":"佚名","dynasty":"先秦","verses":["彼黍离离，彼稷之苗。行迈靡靡，中心摇摇。知我者，谓我心忧；不知我者，谓我何求。悠悠苍天，此何人哉？","彼黍离离，彼稷之穗。行迈靡靡，中心如醉。知我者，谓我心忧；不知我者，谓我何求。悠悠苍天，此何人哉？","彼黍离离，彼稷之实。行迈靡靡，中心如噎。知我者，谓我心忧；不知我者，谓我何求。悠悠苍天，此何人哉？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-64","tags":[]},{"id":"poem-69b6b5beeed06432babd8147","title":"苦寒行","author":"贯休","dynasty":"唐","verses":["北风北风，职何严毒。","摧壮士心，缩金乌足。","冻云嚣嚣，碍雪一片下不得。","声遶枯桑，根在沙塞。","黄河彻底，顽直到海。","一气抟束，万物无态。","唯有吾庭前杉松树枝，枝枝健在。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-342bf50e-e7b2-453f-8b63-69adf2491ce0","tags":["黄河"]},{"id":"poem-69bfbc1b1e64fb4da73aee94","title":"婕妤怨","author":"皇甫冉","dynasty":"唐","verses":["花枝出建章，凤管发昭阳。","借问承恩者，双蛾几许长？"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-婕妤怨","tags":[]},{"id":"poem-69d6c181a93bccb97f2e7d1a","title":"春秋战国门 虞卿","author":"周昙","dynasty":"唐","verses":["割地求和国必危，安知坚守绝来思。","年年来伐年年割，割尽韩郸何所之。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-9f05d684-2335-4aef-9deb-dec38328bb7b","tags":[]},{"id":"poem-69d71ebbdb20937487dae245","title":"读庄子六绝句  其三","author":"李纲","dynasty":"宋","verses":["养生有主卫生经，神守全时岂废形。","游刃有余刀不挫，解牛须是学庖丁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-910f9f00-96b0-42e6-9a1b-bce2f504f2d4","tags":[]},{"id":"poem-69e1b917427e3b1b4298f00f","title":"梁谿八咏 舫斋","author":"李纲","dynasty":"宋","verses":["画舫临流四面通，绿窗面面有清风。","年来始会虚舟意，正在江湖波浪中。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-da626cb1-4a13-43d4-b14e-f4cc0496d23a","tags":[]},{"id":"poem-69e3038ab486073e7dea93a8","title":"赠可上人","author":"李洞","dynasty":"唐","verses":["寺门和鹤倚香杉，月吐秋光到思嚵。","将法传来穿泱漭，把诗吟去入嵌岩。","糢糊书卷烟岚滴，狼籍衣裳瀑布缄。","不断清风牙底嚼，无因内殿得名衔。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-8ec6188a-cfae-416e-b48f-5906b2877810","tags":[]},{"id":"poem-69ecc8cb10aec451fd7f3f0d","title":"静夜思","author":"李白","dynasty":"唐","verses":["床前明月光，疑是地上霜。","举头望明月，低头思故乡。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-靜夜思","tags":[]},{"id":"poem-69fafd98f87982d3d082ccbe","title":"题河中鹳雀楼","author":"张乔","dynasty":"唐","verses":["高楼怀古动悲歌，鹳雀今无野燕过。","树隔五陵秋色早，水连三晋夕阳多。","渔人遗火成寒烧，牧笛吹风起夜波。","十载重来值摇落，天涯归计欲如何。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-c0af0529-265c-4969-9acc-0d9bec5cf709","tags":[]},{"id":"poem-69fc4174aa44890329c1b4d8","title":"出山覩春牓","author":"李洞","dynasty":"唐","verses":["未老鬓毛焦，心归向石桥。","指霞辞二纪，吟雪遇三朝。","连席频登相，分廊尚祝尧。","回眸旧行侣，免使负嵩樵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-faadd68b-ac78-4c56-a848-b81d2ef186e4","tags":[]},{"id":"poem-6a06cf0f66c7a0974e7353a0","title":"资圣寺送甘二","author":"王维","dynasty":"唐","verses":["浮生信如寄，薄宦夫何有。","来往本无归，别离方此受。","柳色蔼春余，槐阴清夏首。","不觉御沟上，衔悲执桮酒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-035eeb3b-429d-4d3c-a8e4-ab063632cfa3","tags":[]},{"id":"poem-6a08c6180301427f763139cb","title":"郊庙歌辞 仪坤庙乐章 雍和","author":"员半千","dynasty":"唐","verses":["孝享云毕，惟彻有章。","云感玄羽，风凄素商。","瞻望神座，祗恋匪遑。","礼终乐阕，肃雍锵锵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-2bcac1d6-b744-4060-9ef5-7f35dad5db8f","tags":[]},{"id":"poem-6a13d6a1495314b9e8b601af","title":"靖康丙午冬道江南宿龟峰寺建炎庚戌秋北归再过行遽不果到长老智光见访成三绝句以遗之  其三","author":"李纲","dynasty":"宋","verses":["兰若松林物外居，羡师一住十年余。","奔驰万里心灰冷，借我峰前使结庐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-b79a21f4-1060-4560-8194-ae1abc7d3862","tags":[]},{"id":"poem-6a22084108edc792a486f23a","title":"防有鹊巢","author":"佚名","dynasty":"先秦","verses":["防有鹊巢，邛有旨苕。谁侜予美？心焉忉忉。","中唐有甓，邛有旨鹝。谁侜予美？心焉惕惕。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-141","tags":[]},{"id":"poem-6a26d3a1178a316eef3b8a9c","title":"春日旅泊桂州","author":"张佖","dynasty":"宋","verses":["暖风芳草竟芊绵，多病多愁负少年。","弱柳未胜寒食雨，好花争奈夕阳天。","溪边物色堪图画，林畔鶑声似管弦。","独有离人开泪眼，强凭杯酒亦潸然。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-d19c7efb-2d4c-4eca-bbff-e25012fbaf93","tags":[]},{"id":"poem-6a2d2fdac979d2a92cd11d7f","title":"题郑少府林园","author":"李端","dynasty":"唐","verses":["谢家今日晚，词客愿抽毫。","枥马方回影，池鹅正理毛。","竹筒传水远，麈尾坐僧高。","独有宗雷贱，过君著敝袍。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-c326aa75-69df-42ec-b918-aacbb8d10860","tags":[]},{"id":"poem-6a37db44ab61583464f1a036","title":"姜秦峰","author":"王十朋","dynasty":"宋","verses":["郡侯不识国元勋，释子那知姜与秦。","隠士有灵应抚掌，相公死亦不容身。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-f06df5e2-df90-4cdc-b012-d72b10cff271","tags":[]},{"id":"poem-6a38de643ad3b5733cfd10d7","title":"青雀歌","author":"卢象","dynasty":"唐","verses":["啾啾青雀儿，飞来飞去仰天池。","逍遥饮啄安涯分，何假扶摇九万为。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-a8c3e791-7f9d-4a6e-baf7-664109545d72","tags":[]},{"id":"poem-6a409e6f1c7068202609e757","title":"答西蜀欧阳侍郎颂（题拟） 三","author":"延沼","dynasty":"唐","verses":["密密堂堂触处周，都缘妄识提浮沤。","三千多泽狂华掩，俊矣天然遇石头。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-c6fbd907-c0cd-41f1-96f0-a3a29e179d4a","tags":[]},{"id":"poem-6a498d246541ea0f33c2e95c","title":"别用韵","author":"司马光","dynasty":"宋","verses":["坐中七叟推年纪，比较前人少几多。","花似锦红头雪白，不游不饮欲如何。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-8e974c06-2aca-4d6b-af45-30befd9bbcd3","tags":[]}];
